                  type="tel"
                  name="mobile"
                  value={formData.mobile}
                  onChange={(e) =>
                    setFormData({ ...formData, mobile: e.target.value.replace(/\D/g, "").slice(0, 10) })
                  }
                  placeholder="10-digit mobile"
                  className="w-full px-4 py-2 focus:outline-none"
                />
              </div>
              <p className="text-xs text-gray-400 mt-1">
                Optional. If set, the user logs in with this number; otherwise with email.
              </p>
            </div>
            <div>
              <label
                htmlFor="password"
                className="block text-gray-700 mb-1 font-medium"
              >
                Password
              </label>
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-400"
                required
              />
            </div>
            <div>
              <label
                htmlFor="role"
                className="block text-gray-700 mb-1 font-medium"
              >
                Role
              </label>
              <select
                name="role"
                value={formData.role}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-400"
              >
                {user?.role === "admin" && (
                  <>
                    <option value="customer">Customer</option>
                    <option value="admin">Admin</option>
                    <option value="merchantise">Merchantise</option>
                    <option value="marketing">Marketing</option>
                    <option value="delivery_boy">Delivery Boy</option>
                  </>
                )}

                {user?.role === "merchantise" && (
                  <>
                    <option value="">Select Role</option>
                    {/* <option value="merchantise">Merchantise</option> */}
                    {/* <option value="marketing">Marketing</option> */}
                    <option value="delivery_boy">Delivery Boy</option>
                  </>
                )}
              </select>
            </div>
          </div>

          <div className="mt-6">
            <button
              type="submit"
              className="bg-green-600 hover:bg-green-700 text-white font-semibold py-2 px-6 rounded shadow"
              disabled={loading}
            >
              {loading ? "Adding..." : "Add User"}
            </button>
          </div>
        </form>
      </div>

      {/* user list management */}
      <div className="bg-white border border-gray-100 shadow-sm rounded-2xl p-6 mt-8">
        <div className="flex flex-wrap items-center justify-between gap-3 mb-5">
          <h3 className="text-lg font-bold text-gray-800">Manage Existing Users</h3>
          <button
            onClick={exportToExcel}
            className="inline-flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-semibold transition"
          >
            <RiFileExcel2Line size={18} /> Export
          </button>
        </div>
        <div className="mb-5 flex flex-col sm:flex-row gap-3">
          <input
            type="text"
            placeholder="Search by name"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400"
          />
          <select
            value={roleFilter}
            onChange={(e) => setRoleFilter(e.target.value)}
            className="sm:w-44 px-4 py-2 border border-gray-300 rounded-lg bg-white focus:outline-none focus:ring-2 focus:ring-blue-400"
          >
            <option value="">All Roles</option>
            <option value="customer">Customer</option>
            <option value="admin">Admin</option>
            <option value="merchantise">Merchantise</option>
            <option value="marketing">Marketing</option>
            <option value="delivery_boy">Delivery Boy</option>
          </select>
        </div>

        <div className="overflow-x-auto rounded-xl border border-gray-100">
          <table className="min-w-full text-sm">
            <thead className="bg-gray-50 text-[11px] uppercase tracking-wider text-gray-500">
              <tr>
                <th className="py-3 px-4 font-semibold text-left">User</th>
                <th className="py-3 px-4 font-semibold text-left">Email</th>
                <th className="py-3 px-4 font-semibold text-left">Phone</th>
                <th className="py-3 px-4 font-semibold text-left">Role</th>
                {/* {user.role === "admin" && (
                  <th className="py-3 px-4 font-semibold text-left">Change Role</th>
                )} */}
                <th className="py-3 px-4 font-semibold text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {paginatedUsers.length > 0 ? (
                paginatedUsers.map((u) => (
                  <tr key={u._id} className="hover:bg-gray-50/70 transition-colors">
                    {/* User */}
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-3">
                        {u.photo ? (
                          <img
                            src={u.photo}
                            alt={u.name}
                            className="w-9 h-9 rounded-full object-cover border border-gray-200 shrink-0"
                          />
                        ) : (
                          <div className="w-9 h-9 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-sm font-bold shrink-0">
                            {(u.name || displayEmail(u) || "?").charAt(0).toUpperCase()}
                          </div>
                        )}
                        <div className="min-w-0">
                          <p className="font-medium text-gray-900 truncate">{u.name || "—"}</p>
                          {u.createdAt && (
                            <p className="text-xs text-gray-400">
                              Joined {new Date(u.createdAt).toLocaleDateString("en-GB", {
                                day: "2-digit",
                                month: "short",
                                year: "numeric",
                              })}
                            </p>
                          )}
                        </div>
                      </div>
                    </td>

                    {/* Email */}
                    <td className="py-3 px-4 text-gray-600 break-all">
                      {displayEmail(u) || <span className="text-gray-300">—</span>}
                    </td>

                    {/* Phone */}
                    <td className="py-3 px-4 whitespace-nowrap font-mono text-gray-600">
                      {u.mobile ? `+91 ${u.mobile}` : <span className="text-gray-300 font-sans">—</span>}
                    </td>

                    {/* Role */}
                    <td className="py-3 px-4">
                      <span
                        className={`inline-block text-xs font-semibold px-3 py-1 rounded-full text-white ${
                          ROLE_STYLES[u.role] || ROLE_STYLES.customer
                        }`}
                      >
                        {roleLabel(u.role)}
                      </span>
                    </td>

                    {/* Change Role */}
                    {/* {user.role === "admin" && (
                      <td className="py-3 px-4">
                        <select
                          value={u.role}
                          onChange={(e) => handleRoleChange(u._id, e.target.value)}
                          className="px-2 py-1.5 border border-gray-200 text-xs rounded-lg bg-white focus:outline-none focus:ring-2 focus:ring-blue-400"
                          disabled={loading}
                        >
                          <option value="customer">Customer</option>
                          {user?.role === "admin" && (
                            <>
                              <option value="admin">Admin</option>
                              <option value="merchantise">Merchantise</option>
                              <option value="marketing">Marketing</option>
                              <option value="delivery_boy">Delivery Boy</option>
                            </>
                          )}
                          {user?.role === "merchantise" && (
                            <option value="delivery_boy">Delivery Boy</option>
                          )}
                        </select>
                      </td>
                    )} */}

                    {/* Actions */}
                    <td className="py-3 px-4">
                      <div className="flex items-center justify-end gap-1.5">
                        <button
                          onClick={() => setViewedUser(u)}
                          title="View details"
                          aria-label="View details"
                          className="w-8 h-8 flex items-center justify-center rounded-lg border border-gray-200 text-gray-500 hover:bg-blue-50 hover:border-blue-200 hover:text-blue-600 transition"
                        >
                          <HiOutlineEye className="text-base" />
                        </button>
                        {(user?.role === "admin" ||
                          (user?.role === "merchantise" && u.role === "delivery_boy")) && (
                          <button
                            onClick={() => openEdit(u)}
                            title="Edit user"
                            aria-label="Edit user"
                            className="w-8 h-8 flex items-center justify-center rounded-lg border border-gray-200 text-gray-500 hover:bg-amber-50 hover:border-amber-200 hover:text-amber-600 transition"
                          >
                            <HiOutlinePencilSquare className="text-base" />
                          </button>
                        )}
                        {user?.role === "admin" && u.role === "customer" && (
                          <button
                            onClick={() => setWalletCreditModal({ userId: u._id, userName: u.name })}
                            title="Credit wallet"
                            aria-label="Credit wallet"
                            className="w-8 h-8 flex items-center justify-center rounded-lg border border-gray-200 text-gray-500 hover:bg-emerald-50 hover:border-emerald-200 hover:text-emerald-600 transition"
                          >
                            <HiOutlineWallet className="text-base" />
                          </button>
                        )}
                        {u._id !== user._id &&
                          (user?.role === "admin" ||
                            (user?.role === "merchantise" && u.role === "delivery_boy")) && (
                            <button
                              onClick={() => handleDeleteUser(u._id)}
                              title="Delete user"
                              aria-label="Delete user"
                              className="w-8 h-8 flex items-center justify-center rounded-lg border border-gray-200 text-gray-500 hover:bg-red-50 hover:border-red-200 hover:text-red-600 transition"
                            >
                              <HiOutlineTrash className="text-base" />
                            </button>
                          )}
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td
                    colSpan={user.role === "admin" ? 6 : 5}
                    className="text-center py-12 text-gray-400"
                  >
                    <p className="text-3xl mb-2">🧑‍🤝‍🧑</p>
                    <p className="text-sm font-medium">
                      {searchTerm || roleFilter ? "No users match your filters" : "No users yet"}
                    </p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination bar */}
        <div className="mt-6 flex flex-col sm:flex-row items-center justify-between gap-4">
          <p className="text-sm text-gray-500 order-2 sm:order-1">
            {filteredUsers.length === 0 ? (
              "No users"
            ) : (
              <>
                Showing{" "}
                <span className="font-semibold text-gray-700">
                  {rangeStart}–{rangeEnd}
                </span>{" "}
                of{" "}
                <span className="font-semibold text-gray-700">
                  {filteredUsers.length}
                </span>{" "}
                users
              </>
            )}
          </p>

          <div className="flex items-center gap-3 order-1 sm:order-2">
            <label className="flex items-center gap-2 text-sm text-gray-500">
              Rows
              <select
                value={usersPerPage}
                onChange={(e) => setUsersPerPage(Number(e.target.value))}
                className="border border-gray-300 rounded-md px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-400"
              >
                {[10, 25, 50, 100].map((n) => (
                  <option key={n} value={n}>
                    {n}
                  </option>
                ))}
              </select>
            </label>

            {totalPages > 1 && (
              <div className="flex items-center gap-1">
                <button
                  type="button"
                  onClick={() => setCurrentPage(page - 1)}
                  disabled={page === 1}
                  aria-label="Previous page"
                  className="w-9 h-9 flex items-center justify-center rounded-md border border-gray-300 text-gray-600 hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  ‹
                </button>

                {buildPageList(page, totalPages).map((p, i) =>
                  p === "…" ? (
                    <span
                      key={`gap-${i}`}
                      className="w-9 h-9 flex items-center justify-center text-gray-400 select-none"
                    >
                      …
                    </span>
                  ) : (
                    <button
                      key={p}
                      type="button"
                      onClick={() => setCurrentPage(p)}
                      aria-current={p === page ? "page" : undefined}
                      className={`min-w-9 h-9 px-2 flex items-center justify-center rounded-md border text-sm font-medium transition ${
                        p === page
                          ? "bg-blue-600 border-blue-600 text-white"
                          : "border-gray-300 text-gray-600 hover:bg-gray-50"
                      }`}
                    >
                      {p}
                    </button>
                  )
                )}

                <button
                  type="button"
                  onClick={() => setCurrentPage(page + 1)}
                  disabled={page === totalPages}
                  aria-label="Next page"
                  className="w-9 h-9 flex items-center justify-center rounded-md border border-gray-300 text-gray-600 hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  ›
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      {confirmModal.visible && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm px-4"
          onClick={closeConfirm}
        >
          <div
            className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 text-center transition-all duration-300 scale-95 animate-fade-in"
            onClick={(e) => e.stopPropagation()}
          >
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Confirm Action</h3>
            <p className="text-sm text-gray-600 mb-6">{confirmModal.message}</p>
            <div className="flex justify-center gap-4">
              <button
                className="px-5 py-2 bg-red-600 text-white rounded hover:bg-red-700"
                onClick={async () => {
                  try {
                    const maybePromise = confirmModal.onConfirm?.();
                    // If onConfirm returned a promise (async), await it
                    if (maybePromise?.then) await maybePromise;
                  } finally {
                    closeConfirm(); // always closes, even if onConfirm throws
                  }
                }}

              >
                Confirm
              </button>
              <button
                className="px-5 py-2 bg-gray-500 text-white rounded hover:bg-gray-600"
                onClick={closeConfirm}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Edit User Modal */}
      {editUser && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm px-4"
          onClick={() => !editSaving && setEditUser(null)}
        >
          <div
            className="bg-white rounded-2xl shadow-xl max-w-md w-full overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 bg-gray-50">
              <h3 className="text-sm font-bold text-gray-800">Edit User</h3>
              <button
                onClick={() => setEditUser(null)}
                disabled={editSaving}
                className="w-8 h-8 flex items-center justify-center rounded-full bg-white border border-gray-200 text-gray-500 hover:bg-gray-100 transition text-lg font-bold disabled:opacity-50"
              >
                ×
              </button>
            </div>

            <div className="p-5 space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1.5">
                  Name
                </label>
                <input
                  type="text"
                  value={editForm.name}
                  onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                  className="w-full px-3 py-2.5 text-sm border border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-300 transition"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1.5">
                  Email <span className="text-gray-400 font-normal normal-case">(optional if phone is set)</span>
                </label>
                <input
                  type="email"
                  value={editForm.email}
                  onChange={(e) => setEditForm({ ...editForm, email: e.target.value })}
                  placeholder="name@example.com"
                  className="w-full px-3 py-2.5 text-sm border border-gray-200 rounded-xl bg-gray-50 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-300 transition"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1.5">
                  Phone Number
                </label>
                <div className="flex rounded-xl border border-gray-200 overflow-hidden focus-within:ring-2 focus-within:ring-blue-300 bg-gray-50 focus-within:bg-white">
                  <span className="bg-gray-100 text-gray-600 text-sm flex items-center px-3 select-none">+91</span>
                  <input
                    type="tel"
                    value={editForm.mobile}
                    onChange={(e) =>
                      setEditForm({ ...editForm, mobile: e.target.value.replace(/\D/g, "").slice(0, 10) })
                    }
                    placeholder="10-digit mobile"
                    className="w-full px-3 py-2.5 text-sm bg-transparent focus:outline-none"
                  />
                </div>
              </div>

              {user?.role === "admin" && (
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1.5">
                    Role
                  </label>
                  <select
                    value={editForm.role}
                    onChange={(e) => setEditForm({ ...editForm, role: e.target.value })}
                    className="w-full px-3 py-2.5 text-sm border border-gray-200 rounded-xl bg-white focus:outline-none focus:ring-2 focus:ring-blue-300 transition"
                  >
                    <option value="customer">Customer</option>
                    <option value="admin">Admin</option>
                    <option value="merchantise">Merchantise</option>
                    <option value="marketing">Marketing</option>
                    <option value="delivery_boy">Delivery Boy</option>
                  </select>
                </div>
              )}

              <div className="flex gap-3 pt-1">
                <button
                  onClick={handleEditSave}
                  disabled={editSaving}
                  className={`flex-1 py-2.5 rounded-xl text-sm font-bold transition ${
                    editSaving
                      ? "bg-gray-100 text-gray-400 cursor-not-allowed"
                      : "bg-blue-600 hover:bg-blue-700 text-white"
                  }`}
                >
                  {editSaving ? "Saving…" : "Save Changes"}
                </button>
                <button
                  onClick={() => setEditUser(null)}
                  disabled={editSaving}
                  className="flex-1 py-2.5 rounded-xl text-sm font-bold border border-gray-200 text-gray-600 hover:bg-gray-50 transition disabled:opacity-50"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* View User Modal */}
      {viewedUser && (() => {
        const uv = viewSummary?.user || viewedUser;
        const s = viewSummary?.stats;
        const fmtINR = (n) => `₹${Number(n || 0).toLocaleString("en-IN")}`;
        const fmtDate = (d) =>
          d ? new Date(d).toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }) : "—";
        const statusPill = (st) => {
          const map = {
            Delivered: "bg-emerald-100 text-emerald-700",
            "RTO Delivered": "bg-emerald-100 text-emerald-700",
            Cancelled: "bg-red-100 text-red-700",
            Refunded: "bg-red-100 text-red-700",
            "RTO Initiated": "bg-red-100 text-red-700",
          };
          return map[st] || "bg-amber-100 text-amber-700";
        };
        const tiles = s
          ? [
              { label: "Total Orders", value: s.total, cls: "text-gray-800" },
              { label: "Successful", value: s.successful, cls: "text-blue-600" },
              { label: "Delivered", value: s.delivered, cls: "text-emerald-600" },
              { label: "Cancelled", value: s.cancelled, cls: "text-red-600" },
              { label: "In Progress", value: s.active, cls: "text-amber-600" },
              { label: "Total Spent", value: fmtINR(s.totalSpent), cls: "text-gray-800", wide: true },
            ]
          : [];

        return (
        <div
          className="fixed inset-0 flex items-center justify-center bg-black/60 z-50 px-4"
          onClick={() => setViewedUser(null)}
        >
          <div
            className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full overflow-hidden max-h-[88vh] flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="bg-linear-to-r from-blue-600 to-indigo-600 p-6 text-white shrink-0">
              <div className="flex items-start gap-4">
                {uv.photo ? (
                  <img
                    src={uv.photo}
                    alt={uv.name}
                    className="w-16 h-16 rounded-full object-cover border-2 border-white/70 shadow shrink-0"
                  />
                ) : (
                  <div className="w-16 h-16 rounded-full bg-white text-blue-600 flex items-center justify-center text-2xl font-bold border-2 border-white/70 shadow shrink-0">
                    {(uv.name || displayEmail(uv) || "?").charAt(0).toUpperCase()}
                  </div>
                )}
                <div className="min-w-0 flex-1">
                  <h3 className="text-xl font-bold truncate">{uv.name || "—"}</h3>
                  <span className="inline-block mt-1 text-[11px] font-semibold px-2.5 py-0.5 rounded-full bg-white/20 capitalize">
                    {roleLabel(uv.role)}
                  </span>
                  <p className="text-sm text-white/85 mt-2 break-all">
                    {displayEmail(uv) || "No email"}
                  </p>
                  <p className="text-sm text-white/85">
                    {uv.mobile ? `+91 ${uv.mobile}` : "No phone"}
                  </p>
                </div>
                <button
                  onClick={() => setViewedUser(null)}
                  className="w-8 h-8 flex items-center justify-center rounded-full bg-white/15 hover:bg-white/25 transition text-lg font-bold shrink-0"
                >
                  ×
                </button>
              </div>
            </div>

            {/* Body */}
            <div className="p-6 space-y-6 overflow-y-auto">
              {viewLoading && (
                <p className="text-sm text-gray-400 text-center py-4">Loading activity…</p>
              )}

              {/* Order stats */}
              {s && (
                <div>
                  <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">
                    Order Activity
                  </p>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                    {tiles.map((t) => (
                      <div
                        key={t.label}
                        className={`rounded-xl border border-gray-100 bg-gray-50 p-3 ${
                          t.wide ? "col-span-2 sm:col-span-3" : ""
                        }`}
                      >
                        <p className={`text-lg font-extrabold ${t.cls}`}>{t.value}</p>
                        <p className="text-[11px] font-medium text-gray-500 uppercase tracking-wide">
                          {t.label}
                        </p>
                      </div>
                    ))}
                  </div>
                  <div className="flex flex-wrap gap-x-6 gap-y-1 mt-3 text-xs text-gray-500">
                    <span>Wallet balance: <strong className="text-gray-800">{fmtINR(viewSummary.walletBalance)}</strong></span>
                    <span>First order: <strong className="text-gray-800">{fmtDate(viewSummary.firstOrderAt)}</strong></span>
                    <span>Last order: <strong className="text-gray-800">{fmtDate(viewSummary.lastOrderAt)}</strong></span>
                  </div>
                </div>
              )}

              {/* Recent orders */}
              {viewSummary?.recentOrders?.length > 0 && (
                <div>
                  <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">
                    Recent Orders
                  </p>
                  <div className="rounded-xl border border-gray-100 divide-y divide-gray-100">
                    {viewSummary.recentOrders.map((o) => (
                      <div key={o._id} className="flex items-center justify-between gap-3 px-3 py-2.5 text-sm">
                        <div className="min-w-0">
                          <p className="font-semibold text-gray-800 truncate">#{o.orderId || o._id.slice(-6)}</p>
                          <p className="text-xs text-gray-400">
                            {fmtDate(o.createdAt)} · {o.paymentMethod || "—"}
                          </p>
                        </div>
                        <span className={`text-[11px] font-semibold px-2 py-0.5 rounded-full shrink-0 ${statusPill(o.status)}`}>
                          {o.status}
                        </span>
                        <span className="font-bold text-gray-800 shrink-0 w-20 text-right">{fmtINR(o.totalPrice)}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {s && s.total === 0 && !viewLoading && (
                <p className="text-sm text-gray-400">This user hasn't placed any orders yet.</p>
              )}

              {/* Addresses */}
              {uv.addresses?.length > 0 && (
                <div>
                  <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">
                    Saved Addresses ({uv.addresses.length})
                  </p>
                  <div className="grid sm:grid-cols-2 gap-3">
                    {uv.addresses.map((addr, idx) => (
                      <div
                        key={addr._id || idx}
                        className="border border-gray-100 bg-gray-50 rounded-xl p-3 text-sm text-gray-600 relative"
                      >
                        {addr.isDefault && (
                          <span className="absolute top-2 right-2 text-[10px] px-2 py-0.5 rounded-full bg-blue-600 text-white font-semibold">
                            Default
                          </span>
                        )}
                        <p className="font-semibold text-gray-800">
                          {[addr.firstName, addr.lastName].filter(Boolean).join(" ") || uv.name}
                        </p>
                        <p className="mt-0.5">{addr.address}{addr.landmark ? `, ${addr.landmark}` : ""}</p>
                        <p>{[addr.city, addr.state, addr.postalCode].filter(Boolean).join(", ")}</p>
                        <p>{addr.country}</p>
                        {addr.phone && <p className="mt-0.5">📞 {addr.phone}</p>}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Meta */}
              <div className="flex flex-wrap gap-x-6 gap-y-1 text-xs text-gray-500 pt-2 border-t border-gray-100">
                <span>User ID: <span className="font-mono text-gray-700">{uv._id}</span></span>
                <span>Joined: <strong className="text-gray-800">{fmtDate(uv.createdAt)}</strong></span>
                {uv.referralCode && <span>Referral code: <strong className="text-gray-800">{uv.referralCode}</strong></span>}
              </div>
            </div>

            {/* Footer */}
            <div className="bg-gray-50 border-t border-gray-100 p-4 flex justify-end gap-3 shrink-0">
              <button
                onClick={() => { setViewedUser(null); openEdit(uv); }}
                className="px-4 py-2 rounded-lg text-sm font-semibold border border-gray-200 text-gray-600 hover:bg-white transition"
              >
                Edit
              </button>
              <button
                onClick={() => setViewedUser(null)}
                className="bg-gray-700 hover:bg-gray-800 text-white px-5 py-2 rounded-lg text-sm font-semibold transition"
              >
                Close
              </button>
            </div>
          </div>
        </div>
        );
      })()}
      {/* ── Admin Wallet Credit Modal ── */}
      {walletCreditModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm px-4"
          onClick={() => setWalletCreditModal(null)}>
          <div className="bg-white rounded-2xl shadow-xl max-w-sm w-full overflow-hidden"
            onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 bg-emerald-50">
              <div>
                <h3 className="text-sm font-bold text-gray-800">Credit Wallet</h3>
                <p className="text-xs text-gray-500 mt-0.5">User: <span className="font-semibold">{walletCreditModal.userName}</span></p>
              </div>
              <button onClick={() => setWalletCreditModal(null)}
                className="w-8 h-8 flex items-center justify-center rounded-full bg-white border border-gray-200 text-gray-500 hover:bg-gray-100 transition text-lg font-bold">
                ×
              </button>
            </div>
            <div className="p-5 space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1.5">Amount (₹)</label>
                <input
                  type="number" min="1" placeholder="e.g. 200"
                  value={walletCreditAmount}
                  onChange={(e) => setWalletCreditAmount(e.target.value)}
                  className="w-full px-3 py-2.5 text-sm border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-300 bg-gray-50 focus:bg-white transition"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1.5">Note (optional)</label>
                <input
                  type="text" placeholder="e.g. Birthday bonus, Refund adjustment…"
                  value={walletCreditNote}
                  onChange={(e) => setWalletCreditNote(e.target.value)}
                  className="w-full px-3 py-2.5 text-sm border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-300 bg-gray-50 focus:bg-white transition"
                />
              </div>
              <div className="flex gap-3 pt-1">
                <button
                  onClick={handleAdminCredit}
                  disabled={walletCreditLoading || !walletCreditAmount || Number(walletCreditAmount) <= 0}
                  className={`flex-1 py-2.5 rounded-xl text-sm font-bold transition ${
                    walletCreditLoading || !walletCreditAmount
                      ? "bg-gray-100 text-gray-400 cursor-not-allowed"
                      : "bg-emerald-600 hover:bg-emerald-700 text-white"
                  }`}
                >
                  {walletCreditLoading ? "Crediting…" : "Credit Wallet"}
                </button>
                <button
                  onClick={() => setWalletCreditModal(null)}
                  className="flex-1 py-2.5 rounded-xl text-sm font-bold border border-gray-200 text-gray-600 hover:bg-gray-50 transition"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserManagement;

import React, { useState, useEffect } from "react";
import { useDispatch } from "react-redux";
import { removeFromCart, updateCartItemQuantity, addToCart } from "../../redux/slices/cartSlice";
import { HiTrash } from "react-icons/hi2";
import { MdBookmarkBorder, MdBookmark } from "react-icons/md";
import axios from "axios";

const SFL_KEY = "saveForLater";

const loadSaved = () => {
  try { return JSON.parse(localStorage.getItem(SFL_KEY) || "[]"); } catch { return []; }
};
const persistSaved = (items) => localStorage.setItem(SFL_KEY, JSON.stringify(items));
const HEX_COLOR_RE = /^#(?:[0-9a-fA-F]{3}){1,2}$/;
const formatColor = (value) => {
  const c = String(value || "").trim();
  if (!c) return "";
  return HEX_COLOR_RE.test(c) ? "Selected Color" : c;
};
const itemKey = (p) =>
  `${String(p?.productId || "")}__${String(p?.size || "")}__${String(p?.color || "")}__${String(p?.sku || "")}`;

const resolveAvailableStock = (product, cartItem) => {
  const size = String(cartItem?.size || "").trim();
  const color = String(cartItem?.color || "").trim();
  const sku = String(cartItem?.sku || "").trim();

  if (Array.isArray(product?.colorVariants) && color && size) {
    const cv = product.colorVariants.find((v) => String(v?.color || "").trim() === color);
    const sizeEntry = cv?.sizes?.find((s) => String(s?.size || "").trim() === size);
    if (sizeEntry) return Number(sizeEntry?.countInStock || 0);
  }

  if (Array.isArray(product?.variants) && sku) {
    const bySku = product.variants.find((v) => String(v?.sku || "").trim() === sku);
    if (bySku) return Number(bySku?.countInStock || 0);
  }

  return Number(product?.countInStock || 0);
};

const CartContents = ({ cart, userId, guestId, onContinueShopping }) => {
  const dispatch = useDispatch();
  const [savedItems, setSavedItems] = useState(loadSaved);
  const [stockByItem, setStockByItem] = useState({});
  const [productMetaByItem, setProductMetaByItem] = useState({});
  const [shippingConfig, setShippingConfig] = useState({ baseShippingFee: 99, freeShippingThreshold: 999 });

  useEffect(() => {
    axios
      .get(`${import.meta.env.VITE_BACKEND_URL}/api/shipping-config`)
      .then(({ data }) => {
        if (data) {
          setShippingConfig({
            baseShippingFee: Number(data.baseShippingFee ?? 99),
            freeShippingThreshold: Number(data.freeShippingThreshold ?? 999),
          });
        }
      })
      .catch(() => {
        // keep the fallback defaults if the config can't be loaded
      });
  }, []);

  const products = cart?.products || [];

  const totalQty = products.reduce((acc, p) => acc + p.quantity, 0);

  const totalAmount = products.reduce(
    (acc, p) => acc + ((p.discountPrice ?? p.price) * p.quantity),
    0
  );

  const originalAmount = products.reduce(
    (acc, p) => acc + (p.price * p.quantity),
    0
  );

  const totalSavings = originalAmount - totalAmount;

  useEffect(() => {
    let cancelled = false;

    const loadStock = async () => {
      if (!products.length) {
        if (!cancelled) setStockByItem({});
        if (!cancelled) setProductMetaByItem({});
        return;
      }

      try {
        const rows = await Promise.all(
          products.map(async (p) => {
            const pid = String(p?.productId || "").trim();
            if (!pid) return [itemKey(p), Number(p?.quantity || 0)];
            const { data } = await axios.get(`${import.meta.env.VITE_BACKEND_URL}/api/products/${pid}`);
            if (!cancelled) {
              setProductMetaByItem((prev) => ({
                ...prev,
                [itemKey(p)]: data,
              }));
            }
            return [itemKey(p), resolveAvailableStock(data, p)];
          })
        );
        if (!cancelled) setStockByItem(Object.fromEntries(rows));
      } catch {
        if (!cancelled) setStockByItem({});
      }
    };

    loadStock();
    return () => {
      cancelled = true;
    };
  }, [products]);

  const handleQty = (productId, delta, quantity, size, color) => {
    const next = quantity + delta;
    if (next >= 1) {
      dispatch(updateCartItemQuantity({ productId, quantity: next, guestId, userId, size, color }));
    }
  };

  const handleRemove = (productId, size, color) => {
    dispatch(removeFromCart({ productId, guestId, userId, size, color }));
  };

  const handleSaveForLater = (product) => {
    dispatch(removeFromCart({ productId: product.productId, guestId, userId, size: product.size, color: product.color }));
    const updated = [
      ...savedItems.filter((s) => !(s.productId === product.productId && s.size === product.size && s.color === product.color)),
      { ...product, savedAt: Date.now() },
    ];
    setSavedItems(updated);
    persistSaved(updated);
  };

  const handleMoveToCart = (item) => {
    dispatch(addToCart({ productId: item.productId, quantity: item.quantity || 1, size: item.size, color: item.color, sku: item.sku, userId, guestId }));
    const updated = savedItems.filter((s) => !(s.productId === item.productId && s.size === item.size && s.color === item.color));
    setSavedItems(updated);
    persistSaved(updated);
  };

  const handleRemoveSaved = (item) => {
    const updated = savedItems.filter((s) => !(s.productId === item.productId && s.size === item.size && s.color === item.color));
    setSavedItems(updated);
    persistSaved(updated);
  };

  // Cart is empty and nothing saved — show empty state
  if (products.length === 0 && savedItems.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] text-center text-gray-600 space-y-4">
        <img
          // src="https://cdn-icons-png.flaticon.com/512/2038/2038854.png"
          src="/trolley.gif"
          alt="Empty Cart"
          className="w-28 h-28 opacity-75"
        />
        <h3 className="text-base font-semibold text-gray-700">Your cart is empty</h3>
        <p className="text-sm text-gray-400">Looks like you haven't added anything yet.</p>
        {onContinueShopping && (
          <button
            onClick={onContinueShopping}
            className="px-5 py-2 bg-sky-600 text-white text-sm font-semibold rounded-lg hover:bg-sky-700 transition"
          >
            Continue Shopping
          </button>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-3">

      {/* ── Product rows ── */}
      {products.map((product, index) => {
        const key = itemKey(product);
        const meta = productMetaByItem[key] || {};
        const originalPrice = Number(meta.price ?? product.price ?? 0);
        const displayPrice = Number(
          meta.displayPrice ??
          meta.discountPrice ??
          product.discountPrice ??
          product.price ??
          0
        );
        const hasDiscount = displayPrice > 0 && displayPrice < originalPrice;
        const lineTotal   = displayPrice * product.quantity;
        const maxStock = Number(stockByItem[key] ?? 0);
        const stockLimitReached = maxStock > 0 && product.quantity >= maxStock;

        return (
          <div
            key={index}
            className="flex items-start gap-4 bg-white border border-gray-100 rounded-2xl p-3.5 hover:border-sky-200 hover:shadow-sm transition-all group"
          >
            {/* Image */}
            <div className="w-20 h-24 rounded-xl overflow-hidden bg-gray-50 border border-gray-100 shrink-0">
              <img
                src={product.image}
                alt={product.name}
                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
              />
            </div>

            {/* Info */}
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold text-gray-800 line-clamp-2 leading-snug">
                {product.name}
              </p>
              <div className="flex flex-wrap gap-1.5 mt-1">
                {product.color && (
                  <span className="text-[10px] font-semibold bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">
                    {formatColor(product.color)}
                  </span>
                )}
                {product.size && (
                  <span className="text-[10px] font-semibold bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">
                    Size: {product.size}
                  </span>
                )}
              </div>

              {/* Price row */}
              <div className="flex items-baseline gap-1.5 mt-2">
                <span className="text-sm font-bold text-gray-900">
                  ₹{displayPrice.toLocaleString("en-IN")}
                </span>
                {hasDiscount && (
                  <span className="text-xs text-gray-400 line-through">
                    ₹{originalPrice.toLocaleString("en-IN")}
                  </span>
                )}
              </div>

              {/* Qty stepper */}
              <div className="flex items-center gap-2 mt-2.5">
                <div className="flex items-center border border-gray-200 rounded-lg overflow-hidden">
                  <button
                    onClick={() => handleQty(product.productId, -1, product.quantity, product.size, product.color)}
                    className="w-7 h-7 flex items-center justify-center text-gray-600 hover:bg-gray-100 transition text-base border-r border-gray-200 font-medium"
                  >
                    −
                  </button>
                  <span className="w-8 text-center text-xs font-bold text-gray-800">
                    {product.quantity}
                  </span>
                  <button
                    onClick={() => {
                      if (totalQty < 10 && !stockLimitReached)
                        handleQty(product.productId, 1, product.quantity, product.size, product.color);
                    }}
                    disabled={totalQty >= 10 || stockLimitReached}
                    className={`w-7 h-7 flex items-center justify-center transition text-base border-l border-gray-200 font-medium
                      ${totalQty >= 10 || stockLimitReached ? "text-gray-300 cursor-not-allowed" : "text-gray-600 hover:bg-gray-100"}`}
                  >
                    +
                  </button>
                </div>
                {totalQty >= 10 && (
                  <p className="text-[10px] text-red-500 font-medium">Max 10 items</p>
                )}
                {totalQty < 10 && maxStock > 0 && (
                  <p className="text-[10px] text-amber-600 font-medium">
                    Only {maxStock} left
                  </p>
                )}
              </div>
            </div>

            {/* Right: total + actions */}
            <div className="flex flex-col items-end justify-between h-24 shrink-0 gap-1">
              <p className="text-sm font-bold text-gray-900">
                ₹{lineTotal.toLocaleString("en-IN")}
              </p>
              <div className="flex items-center gap-1">
                <button
                  onClick={() => handleSaveForLater(product)}
                  className="w-7 h-7 flex items-center justify-center rounded-lg border border-gray-200 text-gray-400 hover:text-sky-600 hover:border-sky-300 hover:bg-sky-50 transition"
                  title="Save for later"
                >
                  <MdBookmarkBorder className="text-sm" />
                </button>
                <button
                  onClick={() => handleRemove(product.productId, product.size, product.color)}
                  className="w-7 h-7 flex items-center justify-center rounded-lg border border-gray-200 text-gray-400 hover:text-red-500 hover:border-red-200 hover:bg-red-50 transition"
                  title="Remove from cart"
                >
                  <HiTrash className="text-sm" />
                </button>
              </div>
            </div>
          </div>
        );
      })}

      {/* ── Coupon badge (if applied) ── */}
      {products.length > 0 && cart?.couponApplied && (
        <div className="flex items-center justify-between bg-emerald-50 border border-emerald-200 rounded-2xl px-4 py-3">
          <div className="flex items-center gap-2">
            <span className="text-emerald-600 text-lg">🎟️</span>
            <div>
              <p className="text-xs font-bold text-emerald-700">Coupon Applied!</p>
              <p className="text-[11px] text-emerald-600 font-mono">COUPON50</p>
            </div>
          </div>
          <span className="text-xs font-bold text-emerald-700 bg-emerald-100 px-3 py-1 rounded-full border border-emerald-200">
            50% OFF
          </span>
        </div>
      )}

      {/* ── Cart Summary ── */}
      {products.length > 0 && (
        <div className="bg-white border border-gray-100 rounded-2xl shadow-sm overflow-hidden">
          {/* Header */}
          <div className="px-4 py-3 border-b border-gray-100 bg-linear-to-r from-sky-50 to-blue-50">
            <p className="text-[11px] font-bold text-sky-700 uppercase tracking-widest">
              Order Summary
            </p>
          </div>

          <div className="px-4 py-4 space-y-2.5">
            {/* Items count */}
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Items ({totalQty})</span>
              <span className="font-semibold text-gray-800">
                ₹{originalAmount.toLocaleString("en-IN")}
              </span>
            </div>

            {/* Discount row */}
            {totalSavings > 0 && (
              <div className="flex items-center justify-between text-sm">
                <span className="text-gray-500">Product Discount</span>
                <span className="font-semibold text-emerald-600">
                  − ₹{totalSavings.toLocaleString("en-IN")}
                </span>
              </div>
            )}

            {/* Shipping estimate */}
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500 flex items-center gap-1.5">
                Delivery
                {totalAmount < shippingConfig.freeShippingThreshold && (
                  <span className="text-[10px] text-amber-600 bg-amber-50 border border-amber-100 px-1.5 py-0.5 rounded-full">
                    Free above ₹{shippingConfig.freeShippingThreshold.toLocaleString("en-IN")}
                  </span>
                )}
              </span>
              {totalAmount >= shippingConfig.freeShippingThreshold ? (
                <span className="font-semibold text-emerald-600">Free</span>
              ) : (
                <span className="font-semibold text-gray-700">₹{shippingConfig.baseShippingFee}</span>
              )}
            </div>

            {/* Total */}
            <div className="border-t border-dashed border-gray-200 pt-2.5">
              <div className="flex items-center justify-between">
                <span className="text-sm font-bold text-gray-900">Total Amount</span>
                <span className="text-lg font-extrabold text-sky-700">
                  ₹{(totalAmount + (totalAmount >= shippingConfig.freeShippingThreshold ? 0 : shippingConfig.baseShippingFee)).toLocaleString("en-IN")}
                </span>
              </div>
              {totalSavings > 0 && (
                <p className="text-[11px] text-emerald-600 font-semibold mt-1 text-right">
                  You save ₹{totalSavings.toLocaleString("en-IN")} 🎉
                </p>
              )}
              {totalAmount < shippingConfig.freeShippingThreshold && (
                <p className="text-[11px] text-amber-600 mt-1 text-right">
                  Add ₹{(shippingConfig.freeShippingThreshold - totalAmount).toLocaleString("en-IN")} more for free shipping
                </p>
              )}
            </div>
          </div>

          {/* Trust badges */}
          <div className="flex items-center justify-center gap-4 px-4 py-3 border-t border-gray-100 bg-gray-50">
            {[
              { icon: "🔒", text: "Secure Checkout" },
              { icon: "🚚", text: "Free Delivery" },
              { icon: "↩", text: "Easy Returns" },
            ].map(({ icon, text }) => (
              <span key={text} className="flex items-center gap-1 text-[10px] font-medium text-gray-400">
                {icon} {text}
              </span>
            ))}
          </div>
        </div>
      )}
      {/* ── Saved for Later ── */}
      {savedItems.length > 0 && (
        <div className="mt-4">
          <div className="flex items-center gap-2 mb-3">
            <MdBookmark className="text-sky-500" />
            <p className="text-sm font-bold text-gray-700">
              Saved for Later ({savedItems.length})
            </p>
          </div>
          <div className="space-y-2">
            {savedItems.map((item, i) => (
              <div
                key={i}
                className="flex items-center gap-3 bg-gray-50 border border-gray-100 rounded-2xl p-3"
              >
                <div className="w-14 h-16 rounded-lg overflow-hidden bg-white border border-gray-100 shrink-0">
                  <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-semibold text-gray-800 line-clamp-1">{item.name}</p>
                  <p className="text-[10px] text-gray-400 mt-0.5">
                    {item.color && <span>{formatColor(item.color)}</span>}
                    {item.color && item.size && <span> · </span>}
                    {item.size && <span>Size: {item.size}</span>}
                  </p>
                  <p className="text-xs font-bold text-gray-900 mt-1">
                    ₹{Number(
                      productMetaByItem[itemKey(item)]?.displayPrice ??
                      productMetaByItem[itemKey(item)]?.discountPrice ??
                      item.discountPrice ??
                      item.price ??
                      0
                    ).toLocaleString("en-IN")}
                  </p>
                </div>
                <div className="flex flex-col gap-1 shrink-0">
                  <button
                    onClick={() => handleMoveToCart(item)}
                    className="text-[10px] font-bold text-sky-700 border border-sky-300 bg-sky-50 hover:bg-sky-100 px-2 py-1 rounded-lg transition whitespace-nowrap"
                  >
                    Move to Cart
                  </button>
                  <button
                    onClick={() => handleRemoveSaved(item)}
                    className="text-[10px] font-medium text-gray-400 hover:text-red-500 transition text-center"
                  >
                    Remove
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default CartContents;

import React, { useEffect, useState } from "react";
