        >
          <div
            className={`bg-white rounded-xl shadow-2xl p-8 max-w-sm w-full relative transform ${showModal ? "animate-[fadeInScale_0.25s_ease-out]" : "animate-[fadeOutScale_0.2s_ease-in]"
