export default DropDetail;

import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { toast } from "sonner";

const EditCollab = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [collab, setCollab] = useState(null);
  const [allProducts, setAllProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [activeTab, setActiveTab] = useState(0);
  const token = localStorage.getItem("userToken");

  useEffect(() => {
    const fetchCollab = async () => {
      try {
        const { data } = await axios.get(
          `${import.meta.env.VITE_BACKEND_URL}/api/collabs/${id}`
        );
        setCollab(data);
      } catch {
        toast.error("Failed to fetch collab");
      }
    };

    const fetchProducts = async () => {
      const { data } = await axios.get(
        `${import.meta.env.VITE_BACKEND_URL}/api/products`
      );
      setAllProducts(data);
    };

    fetchCollab();
    fetchProducts();
  }, [id]);

  const handleChange = (field, value) => {
    setCollab({ ...collab, [field]: value });
  };

  const handleCollaboratorChange = (index, field, value) => {
    const updated = [...collab.collaborators];
    updated[index][field] = value;
    setCollab({ ...collab, collaborators: updated });
  };

  const handleProductToggle = (index, productId) => {
    const updated = [...collab.collaborators];
    const exists = updated[index].products.includes(productId);
    updated[index].products = exists
      ? updated[index].products.filter((id) => id !== productId)
      : [...updated[index].products, productId];
    setCollab({ ...collab, collaborators: updated });
  };

  const handleBannerUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append("image", file);

    try {
      setUploading(true);
      const { data } = await axios.post(
        `${import.meta.env.VITE_BACKEND_URL}/api/upload`,
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
            Authorization: `Bearer ${token}`,
          },
        }
      );
      setCollab({ ...collab, image: data.imageUrl });
      toast.success("Banner image uploaded");
    } catch {
      toast.error("Banner upload failed");
    } finally {
      setUploading(false);
    }
  };

  const handleCollaboratorImageUpload = async (e, index) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append("image", file);

    try {
      setUploading(true);
      const { data } = await axios.post(
        `${import.meta.env.VITE_BACKEND_URL}/api/upload`,
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const updated = [...collab.collaborators];
      updated[index].image = data.imageUrl;
      setCollab({ ...collab, collaborators: updated });

      toast.success(`Image uploaded for Footballer ${index + 1}`);
    } catch {
      toast.error("Footballer image upload failed");
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await axios.put(
        `${import.meta.env.VITE_BACKEND_URL}/api/collabs/${id}`,
        collab
      );
      toast.success("Collab updated successfully");
      navigate("/admin/collabs");
    } catch {
      toast.error("Failed to update collab");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteCollaborator = (index) => {
    const updated = [...collab.collaborators];
    updated.splice(index, 1);
    setCollab({ ...collab, collaborators: updated });
  };

  if (!collab) return <p className="text-center mt-10">Loading...</p>;

  return (
    <div className="max-w-4xl mx-auto p-6 bg-white/80 backdrop-blur-xl shadow-2xl rounded mt-10 border border-gray-200">
      <h2 className="text-3xl font-extrabold mb-8 text-slate-800 text-center tracking-wide">
        Edit Collaboration
      </h2>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* Banner Upload */}
        <div>
          <label className="font-semibold text-gray-700 block mb-2 text-sm">
            Collab Banner Image
          </label>
          <input
            type="file"
            accept="image/*"
            onChange={handleBannerUpload}
            className="file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-sky-100 file:text-sky-700 hover:file:bg-sky-200"
          />
          {collab.image && (
            <img
              src={collab.image}
              alt="Banner"
              className="h-32 mt-4 rounded-lg object-cover border-2 border-sky-200 shadow"
            />
          )}
        </div>

        {/* Collab Title */}
        <input
          type="text"
          value={collab.title}
          onChange={(e) => handleChange("title", e.target.value)}
          className="w-full border border-gray-300 rounded-lg px-4 py-3 text-gray-700 focus:outline-none focus:ring-2 focus:ring-sky-400"
          placeholder="Collab Title"
        />

        {/* Collab Description */}
        <textarea
          value={collab.description || ""}
          onChange={(e) => handleChange("description", e.target.value)}
          className="w-full border border-gray-300 rounded-lg px-4 py-3 text-gray-700 focus:outline-none focus:ring-2 focus:ring-sky-400"
          placeholder="Collab Description"
        />

        {/* Publish Toggle */}
        <div className="flex items-center gap-4">
          <label className="text-sm font-medium text-gray-700">Publish:</label>
          <button
            type="button"
            onClick={() => handleChange("isPublished", !collab.isPublished)}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition ${
              collab.isPublished ? "bg-green-500" : "bg-gray-300"
            }`}
          >
            <span
              className={`inline-block h-4 w-4 transform rounded-full bg-white transition ${
                collab.isPublished ? "translate-x-6" : "translate-x-1"
              }`}
            />
          </button>
          <span
            className={`text-xs font-semibold ${
              collab.isPublished ? "text-green-600" : "text-gray-500"
            }`}
          >
            {collab.isPublished ? "Published" : "Draft"}
          </span>
        </div>

        {/* Collaborator Tabs */}
        <div className="space-y-4">
          <div className="flex flex-wrap gap-2">
            {collab.collaborators.map((person, idx) => (
              <button
                key={idx}
                type="button"
                onClick={() => setActiveTab(idx)}
                className={`px-4 py-1 rounded-full text-sm font-semibold border ${
                  activeTab === idx
                    ? "bg-sky-500 text-white border-sky-500"
                    : "text-sky-600 border-sky-300 hover:bg-sky-100"
                }`}
              >
                {person.name || `Footballer ${idx + 1}`}
              </button>
            ))}
          </div>

          {collab.collaborators.map((person, idx) =>
            activeTab === idx ? (
              <div
                key={idx}
                className="relative border border-gray-300 p-6 rounded-2xl bg-white shadow-sm space-y-4 pt-12"
              >
                <button
                  onClick={() => handleDeleteCollaborator(idx)}
                  className="absolute top-1 right-2 bg-red-500 hover:bg-red-700 text-xl font-bold text-white rounded-full w-8 h-8 flex items-center justify-center transition-all"
                  title="Remove Footballer"
                >
                  &times;
                </button>

                <input
                  type="text"
                  value={person.name}
                  onChange={(e) =>
                    handleCollaboratorChange(idx, "name", e.target.value)
                  }
                  placeholder="Footballer Name"
                  className="w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-pink-400 outline-0"
                />

                <input
                  type="file"
                  accept="image/*"
                  onChange={(e) => handleCollaboratorImageUpload(e, idx)}
                  className="file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-pink-100 file:text-pink-700 hover:file:bg-pink-200"
                />

                {person.image && (
                  <img
                    src={person.image}
                    alt="footballer"
                    className="h-24 rounded-lg border-2 border-pink-200 object-cover mt-2"
                  />
                )}

                <p className="text-sm font-semibold text-gray-600">
                  Used Products:
                </p>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3 max-h-44 overflow-y-auto p-2 border border-gray-200 rounded-md bg-gray-50">
                  {allProducts.map((product) => (
                    <label
                      key={product._id}
                      className="flex items-center gap-2 text-sm text-gray-700"
                    >
                      <input
                        type="checkbox"
                        checked={person.products.some((p) =>
                          typeof p === "object"
                            ? p._id === product._id
                            : p === product._id
                        )}
                        onChange={() => handleProductToggle(idx, product._id)}
                        className="accent-sky-500"
                      />
                      <span>{product.name}</span>
                    </label>
                  ))}
                </div>
              </div>
            ) : null
          )}
        </div>

        {/* Submit Button */}
        <div className="text-right pt-4">
          <button
            type="submit"
            disabled={loading}
            className="bg-gradient-to-r from-blue-600 to-sky-500 text-white px-8 py-3 rounded-full font-semibold hover:opacity-90 shadow-lg transition-all"
          >
            {loading ? "Saving..." : "Update Collab"}
          </button>
        </div>
      </form>
    </div>
  );
};

export default EditCollab;

import React, { useEffect, useState } from "react";
import axios from "axios";
import { toast } from "sonner";
import { FaArrowRight } from "react-icons/fa";
import { motion } from "framer-motion";
// import ProductGrid from "../components/Products/ProductGrid";
import { useNavigate } from "react-router-dom";

const ExclusiveDrop = () => {
  const navigate = useNavigate();
  const [exclusiveDrops, setExclusiveDrops] = useState([]);
  const [flippedCard, setFlippedCard] = useState(null);
  const [dropDetails, setDropDetails] = useState(null);
  const [loading, setLoading] = useState(false);
  const [featuredCollab, setFeaturedCollab] = useState(null);


  useEffect(() => {
    const fetchCollab = async () => {
      try {
        const { data } = await axios.get(`${import.meta.env.VITE_BACKEND_URL}/api/collabs`);
        if(data && data.length > 0) {
          setFeaturedCollab(data[0]);
        }
      } catch (err) {
        console.error("Failed to load featured collab", err);
      }
    };
    fetchCollab();
  }, []);

  // Fetch all drops
  useEffect(() => {
    const fetchDrops = async () => {
      try {
        const { data } = await axios.get(
          `${import.meta.env.VITE_BACKEND_URL}/api/collabs`
        );
        setExclusiveDrops(data);
      } catch (err) {
        toast.error("Failed to load exclusive drops");
      }
    };
    fetchDrops();
  }, []);

  // Fetch drop detail when footballer selected
  useEffect(() => {
    if (!flippedCard) return;
    const fetchDropData = async () => {
      setLoading(true);
      try {
        const slug = flippedCard.toLowerCase().replace(/\s+/g, "-");
        const { data } = await axios.get(
          `${import.meta.env.VITE_BACKEND_URL}/api/collabs/footballer/${slug}`
        );
        setDropDetails(data);
      } catch (err) {
        toast.error("Drop not found or unpublished");
        setDropDetails(null);
      } finally {
        setLoading(false);
      }
    };
    fetchDropData();
  }, [flippedCard]);

  return (
    // <section className="container mx-auto px-4 py-14">
    <motion.section
      initial={{ x: "100%", opacity: 0 }}
      animate={{ x: 0, opacity: 1 }}
      transition={{ type: "tween", duration: 0.45, ease: "easeOut" }}
      className="container mx-auto px-4 py-14"
    >
      {/* Header */}
      <div className="text-center mb-12">
        <span className="inline-block text-xs font-semibold bg-gradient-to-r from-sky-600 to-blue-600 text-white px-4 py-1 rounded-full uppercase tracking-widest mb-3">
          Limited Edition
        </span>
        <h2 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-sky-400">
          Exclusive Drops
        </h2>
        <p className="text-gray-600 mt-2 text-sm font-medium">
          {featuredCollab?.title || "Featured Collab"} x Raphaa Limited Edition
        </p>
      </div>

      {/* Grid of flip cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-2 gap-10 perspective">
        {exclusiveDrops.flatMap((collab, index) =>
          collab.collaborators.map((person, i) => {
            const isFlipped = flippedCard === person.name;
            return (
              <motion.div
                key={`${collab._id}-${i}`}
                className={`relative w-full h-[450px] cursor-pointer`}
                onClick={() =>
                  setFlippedCard(isFlipped ? null : person.name)
                }
              >
                <motion.div
                  className={`absolute inset-0 transition-transform duration-700 preserve-3d ${isFlipped ? "rotate-y-180" : ""
                    }`}
                >
                  {/* Front Side */}
                  <div className="absolute inset-0 backface-hidden rounded-3xl overflow-hidden shadow-lg">
                    <img
                      src={person.image}
                      alt={person.name}
                      className="h-full w-full object-cover hover:scale-105 transition-all"
                      loading="lazy"
                    />
                    <div className="absolute bottom-0 left-0 right-0 bg-black/80 p-4 text-white flex flex-wrap justify-between items-center">
                      <div>
                        <h3 className="text-xl font-bold">{person.name}</h3>
                        <p className="text-sm">
                          {person.products?.[0]?.name || "Exclusive Drop"}
                        </p>
                      </div>
                      <p className="relative text-white px-4 py-1 rounded-full overflow-hidden">
                        <span className="absolute inset-0 animate-gradient bg-[length:200%_200%] bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500"></span>
                        <span className="relative z-10">Click here to view drops</span>
                      </p>
                    </div>
                  </div>

                  {/* Back Side */}
                  <div className="absolute inset-0 backface-hidden rotate-y-180 rounded-3xl bg-white shadow-xl p-6 overflow-y-auto custom-scrollbar">
                    {loading && <p>Loading...</p>}
                    {/* Suggested Products Section */}
                    {dropDetails?.products?.length > 0 && (
                      <div className="">
                        <h3 className="text-2xl font-bold mb-4">
                          Special drop: <span className="text-blue-500">{dropDetails.footballer}</span>
                        </h3>
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-3 gap-1">
                          {dropDetails.products.slice(0, 4).map((product) => (
                            <div
                              key={product._id}
                              onClick={() =>
                                navigate(
                                  `/product/${product.name.toLowerCase().replace(/\s+/g, "-")}`
                                )
                              }
                              className="cursor-pointer rounded-lg border border-gray-200 hover:shadow-xl transition-all duration-300 bg-gradient-to-br from-blue-100 via-sky-200 to-sky-100"
                            >
                              <img
                                src={product.images?.[0]?.url || "/no-image.png"}
                                alt={product.name}
                                className="w-full h-40 object-cover rounded-t-lg hover:scale-95 transition-transform duration-300"
                              />
                              <div className="px-3 py-2">
                                <h4 className="text-sm font-medium text-gray-800 truncate">
                                  {product.name}
                                </h4>
                                <div className="inline-flex items-center gap-2 bg-green-600 text-white text-xs mt-1 px-2 py-0.5 rounded">
                                  ★ {product.rating?.toFixed(1) || "0.0"}
                                </div>
                                <p className="text-xs text-gray-500 mt-1">
                                  {product.numReviews || 0} Reviews
                                </p>
                                <div className="flex items-center gap-2 mt-1">
                                  <p className="text-sm font-bold text-blue-600">
                                    ₹{Math.floor(product.discountPrice || product.price)}
                                  </p>
                                  {product.discountPrice && (
                                    <p className="text-xs line-through text-gray-500">
                                      ₹{product.price}
                                    </p>
                                  )}
                                  <p className="text-sm text-green-600">
                                    {product.offerPercentage ? `${product.offerPercentage}%` : ""}
                                  </p>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); setFlippedCard(null); setDropDetails(null); }} className="mt-4 px-4 py-2 bg-gradient-to-r from-red-500 to-pink-500 text-white rounded-full text-sm font-semibold shadow hover:scale-105 transition" > ← Back </button>
                      </div>
                    )}
                  </div>
                </motion.div>
              </motion.div>
            );
          })
        )}
      </div>
    {/* </section> */}
    </motion.section>
  );
};

