              >
                {position}
              </button>
            ))}
          </div>
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-2">Overlay Direction</label>
          <div className="grid grid-cols-2 gap-2">
