            </div>
          ))}
        </div>
      )}

      {/* ── MODAL ── */}
      {modal && (
        <div
          className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm overflow-y-auto flex items-start justify-center pt-6 pb-10 px-4"
