    </div>
  );
}

import React, { useEffect, useState } from "react";
import { toast } from "sonner";
import {
  Chart as ChartJS,
  ArcElement,
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar, Pie } from "react-chartjs-2";

ChartJS.register(
  ArcElement,
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend
);

const InventoryPage = () => {
  const [products, setProducts] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [priceRange, setPriceRange] = useState([0, 10000]);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;

  const userInfo = JSON.parse(localStorage.getItem("userInfo"));

  useEffect(() => {
    const fetchInventory = async () => {
      try {
        const res = await fetch(
          `${import.meta.env.VITE_BACKEND_URL}/api/products/inventory`,
          {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("userToken")}`,
            },
          }
        );
        if (!res.ok) {
          throw new Error("Failed to fetch inventory");
        }
        const data = await res.json();
        setProducts(data);
        setFiltered(data);
      } catch (err) {
        toast.error("Failed to load inventory");
      }
    };

    if (userInfo?.role === "admin" || userInfo?.role === "merchantise") {
      fetchInventory();
    }
  }, []);

  // Handle filter changes
  useEffect(() => {
    let data = [...products];

    if (categoryFilter !== "all") {
      data = data.filter(
        (item) => item.category?.toLowerCase() === categoryFilter
      );
    }

    data = data.filter(
      (item) => item.price >= priceRange[0] && item.price <= priceRange[1]
    );

    setFiltered(data);
    setCurrentPage(1); // reset page on filter
  }, [categoryFilter, priceRange, products]);

  // Pagination
  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const paginatedData = filtered.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const categories = [
    ...new Set(products.map((item) => item.category?.toLowerCase())),
  ];

  return (
    <div className="max-w-7xl mx-auto p-6">
      <h2 className="text-2xl font-bold mb-6">Inventory & Stock Tracking</h2>

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6 mb-6 bg-white/70 backdrop-blur-md border border-gray-200 p-4 rounded-xl shadow-sm">
        {/* Left Section: Category + Price */}
        <div className="flex flex-wrap items-center gap-6">
          {/* Category */}
          <div className="flex items-center gap-3">
            <label className="text-xs font-semibold text-gray-600 uppercase tracking-wide">
              Category
            </label>
            <select
              value={categoryFilter}
              onChange={(e) => setCategoryFilter(e.target.value)}
              className="bg-white px-3 py-2 rounded-lg outline-none border border-gray-300 text-gray-700 shadow-sm hover:border-sky-400 focus:ring-2 focus:ring-sky-400 transition"
            >
              <option value="all">All</option>
              {categories.map((cat, idx) => (
                <option key={idx} value={cat}>
                  {cat.charAt(0).toUpperCase() + cat.slice(1)}
                </option>
              ))}
            </select>
          </div>

          {/* Price */}
          <div className="flex items-center gap-3">
            <label className="text-xs font-semibold text-gray-600 uppercase tracking-wide">
              Price
            </label>
            <input
              type="number"
              className="w-24 border border-gray-300 px-3 py-2 rounded-lg bg-white text-gray-700 outline-none shadow-sm hover:border-sky-400 focus:ring-2 focus:ring-sky-400 transition"
              value={priceRange[0]}
              onChange={(e) =>
                setPriceRange([Number(e.target.value), priceRange[1]])
              }
              placeholder="Min"
            />
            <span className="text-gray-500 font-medium">-</span>
            <input
              type="number"
              className="w-24 border border-gray-300 px-3 py-2 rounded-lg bg-white text-gray-700 outline-none shadow-sm hover:border-sky-400 focus:ring-2 focus:ring-sky-400 transition"
              value={priceRange[1]}
              onChange={(e) =>
                setPriceRange([priceRange[0], Number(e.target.value)])
              }
              placeholder="Max"
            />
          </div>
        </div>

        {/* Right Section: Reset Button */}
        <div className="flex justify-end">
          <button
            onClick={() => {
              setCategoryFilter("all");
              setPriceRange([0, 0]);
            }}
            className="px-5 py-2 rounded-lg font-semibold text-white bg-gradient-to-r from-sky-500 to-blue-600 shadow-md hover:shadow-lg hover:scale-105 transition-all"
          >
            Clear Filters
          </button>
        </div>
      </div>



      {products.length > 0 && (
        <div className="space-y-8 mb-10">
          {/* Bar Chart */}
          <div className="bg-white/80 backdrop-blur-md p-6 rounded-2xl shadow-lg border border-gray-200">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                Stock Count per Product
              </h3>
            </div>
            <Bar
              data={{
                labels: products.map((p) => p.name),
                datasets: [
                  {
                    label: "Stock Count",
                    data: products.map((p) => p.countInStock),
                    backgroundColor: function (context) {
                      const chart = context.chart;
                      const { ctx, chartArea } = chart;

                      if (!chartArea) return null; // chart not ready yet

                      const gradient = ctx.createLinearGradient(0, 0, 0, chartArea.bottom);
                      gradient.addColorStop(0, "rgba(56,189,248,0.9)");  // sky-400
                      gradient.addColorStop(1, "rgba(99,102,241,0.9)"); // indigo-500

                      return gradient;
                    },
                  },
                ],
              }}
              options={{
                responsive: true,
                plugins: {
                  legend: { display: false },
                },
                scales: {
                  y: {
                    beginAtZero: true,
                    ticks: {
                      stepSize: 1,
                      color: "#374151",
                      font: { weight: "600" },
                    },
                    grid: { color: "#e5e7eb" },
                  },
                  x: {
                    ticks: {
                      color: "#6b7280",
                      font: { weight: "500" },
                    },
                    grid: { display: false },
                  },
                },
              }}
            />
          </div>

          {/* Pie Chart */}
          {/* <div className="bg-white/80 backdrop-blur-md p-6 rounded-2xl shadow-lg border border-gray-200">
            <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
              🥧 Stock by Category
            </h3>
            <Pie
              data={{
                labels: [...new Set(products.map((p) => p.category))],
                datasets: [
                  {
                    label: "Stock by Category",
                    data: [...new Set(products.map((p) => p.category))].map((cat) =>
                      products
                        .filter((p) => p.category === cat)
                        .reduce((acc, curr) => acc + curr.countInStock, 0)
                    ),
                    backgroundColor: [
                      "#6366f1",
                      "#f59e0b",
                      "#10b981",
                      "#ef4444",
                      "#8b5cf6",
                      "#ec4899",
                    ],
                    borderWidth: 2,
                    borderColor: "#fff",
                  },
                ],
              }}
              options={{
                responsive: true,
                plugins: {
                  legend: {
                    position: "bottom",
                    labels: {
                      color: "#374151",
                      padding: 16,
                      font: { size: 12, weight: "500" },
                    },
                  },
                },
              }}
            />
          </div> */}
        </div>
      )}


      <div className="overflow-x-auto rounded-xl shadow-lg border border-gray-200">
        <table className="min-w-full divide-y divide-gray-200 bg-white rounded-xl overflow-hidden">
          {/* Table Head */}
          <thead className="bg-gradient-to-r from-sky-50 to-blue-50">
            <tr>
              <th className="px-6 py-4 text-left text-sm font-bold text-gray-700">Product</th>
              <th className="px-6 py-4 text-left text-sm font-bold text-gray-700">Variants</th>
              <th className="px-6 py-4 text-left text-sm font-bold text-gray-700">Category</th>
              <th className="px-6 py-4 text-left text-sm font-bold text-gray-700">Price</th>
              <th className="px-6 py-4 text-left text-sm font-bold text-gray-700">Stock</th>
              <th className="px-6 py-4 text-left text-sm font-bold text-gray-700">Status</th>
            </tr>
          </thead>

          {/* Table Body */}
          <tbody className="divide-y divide-gray-100 text-sm">
            {paginatedData.map((prod, idx) => (
              <tr
                key={prod._id}
                className={`transition hover:bg-sky-50 ${idx % 2 === 0 ? "bg-white" : "bg-gray-50/50"
                  }`}
              >
                {/* Product */}
                <td className="px-6 py-4 font-medium text-gray-800">{prod.name}</td>

                {/* Variants */}
                <td className="px-6 py-4 text-xs text-gray-600">
                  {Array.isArray(prod.colorVariants) && prod.colorVariants.length > 0 ? (
                    <>
                      <div className="font-semibold text-gray-800">
                        {prod.colorVariants.length} color{prod.colorVariants.length > 1 ? "s" : ""}
                        {" · "}
                        {prod.colorVariants.reduce((s, cv) => s + (cv.sizes?.length || 0), 0)} sizes
                      </div>
                      <div className="flex flex-wrap gap-1 mt-0.5">
                        {prod.colorVariants.slice(0, 3).map((cv, i) => (
                          <span key={i} className="inline-flex items-center gap-1 bg-gray-100 px-1.5 py-0.5 rounded">
                            <span className="w-2.5 h-2.5 rounded-full border border-gray-300 inline-block" style={{ backgroundColor: cv.color }} />
                            {cv.colorName || cv.color}
                          </span>
                        ))}
                        {prod.colorVariants.length > 3 && <span className="text-gray-400">+{prod.colorVariants.length - 3}</span>}
                      </div>
                    </>
                  ) : Array.isArray(prod.variants) && prod.variants.length > 0 ? (
                    <>
                      <div className="font-semibold text-gray-800">
                        {prod.variants.length} variant{prod.variants.length > 1 ? "s" : ""}
                      </div>
                      <div>
                        {prod.variants.slice(0, 2).map((v) => `${v.color}/${v.size}`).join(", ")}
                        {prod.variants.length > 2 ? "…" : ""}
                      </div>
                    </>
                  ) : (
                    <span className="italic text-gray-400">No variants</span>
                  )}
                </td>

                {/* Category */}
                <td className="px-6 py-4 capitalize text-gray-600">{prod.category}</td>

                {/* Price */}
                <td className="px-6 py-4 font-semibold text-gray-900">₹{prod.price}</td>

                {/* Stock Count */}
                <td className="px-6 py-4 font-bold">
                  <span
                    className={`${prod.countInStock <= 5 ? "text-red-600" : "text-green-600"
                      }`}
                  >
                    {prod.countInStock}
                  </span>
                </td>

                {/* Status */}
                <td className="px-6 py-4">
                  <span
                    className={`flex items-center justify-center gap-1 text-xs font-semibold px-3 py-1 rounded-full w-fit ${prod.countInStock === 0
                      ? "bg-red-100 text-red-700"
                      : prod.countInStock <= 5
                        ? "bg-yellow-100 text-yellow-700"
                        : "bg-green-100 text-green-700"
                      }`}
                  >
                    {prod.countInStock === 0 ? (
                      <>Out of Stock</>
                    ) : prod.countInStock <= 5 ? (
                      <>Low Stock</>
                    ) : (
                      <>In Stock</>
                    )}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>


      {/* Pagination */}
      <div className="mt-6 flex justify-center gap-2">
        {Array.from({ length: totalPages }, (_, idx) => (
          <button
            key={idx}
            className={`px-3 py-1 rounded-full ${currentPage === idx + 1
              ? "bg-indigo-600 text-white"
              : "bg-gray-400 text-white hover:bg-gray-500"
              }`}
            onClick={() => setCurrentPage(idx + 1)}
          >
            {idx + 1}
          </button>
        ))}
      </div>
    </div>
  );
};

export default InventoryPage;

import React, { useState, useEffect, useRef } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { loginUser, googleLoginSuccess } from "../redux/slices/authSlice";
import { useDispatch, useSelector } from "react-redux";
import { mergecart } from "../redux/slices/cartSlice";
import { toast } from "sonner";
import { FiRefreshCcw } from "react-icons/fi";
import { GoogleLogin } from "@react-oauth/google";
import { jwtDecode } from "jwt-decode";
import axios from "axios";
import { FaEye, FaEyeSlash, FaWhatsapp } from "react-icons/fa";

const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loginMode, setLoginMode] = useState("otp"); // "password" | "otp"
  const [otpMobileTouched, setOtpMobileTouched] = useState(false);
  const [otpMobile, setOtpMobile] = useState("");
  const [otpCode, setOtpCode] = useState("");
  const [otpStep, setOtpStep] = useState("mobile"); // "mobile" | "otp" | "name"
  const [otpName, setOtpName] = useState("");
  const [otpLoading, setOtpLoading] = useState(false);
  const [captchaAnswer, setCaptchaAnswer] = useState("");
  const [captchaQuestion, setCaptchaQuestion] = useState({});
  const [requiresCaptcha, setRequiresCaptcha] = useState(false);
  const canvasRef = useRef(null);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const { user, guestId, loading } = useSelector((state) => state.auth);
  const { cart } = useSelector((state) => state.cart);
  const [showPassword, setShowPassword] = useState(false);

  const redirectParam = new URLSearchParams(location.search).get("redirect");
  const redirect =
    redirectParam && redirectParam.startsWith("/") ? redirectParam : "/";

  useEffect(() => {
    if (user) {
      if (!sessionStorage.getItem("loginToastShown")) {
        sessionStorage.setItem("loginToastShown", "1");
        toast.success("Login successful!");
      }

      if (["admin", "merchantise", "marketing"].includes(user.role)) {
        navigate("/admin");
        return;
      }
      if (cart?.products.length > 0 && guestId) {
        dispatch(mergecart({ guestId, user })).then(() => {
          navigate(redirect);
        });
      } else {
        navigate(redirect);
      }
    }
  }, [user, guestId, cart, navigate, redirect, dispatch]);

  useEffect(() => {
    sessionStorage.removeItem("loginToastShown");
  }, []);

  useEffect(() => {
    const normalized = email.toLowerCase().trim();
    if (!validateEmail(normalized)) {
      setRequiresCaptcha(false);
      setCaptchaAnswer("");
      return;
    }

    const timer = setTimeout(async () => {
      try {
        const { data } = await axios.post(
          `${import.meta.env.VITE_BACKEND_URL}/api/users/prelogin-role`,
          { email: normalized }
        );
        setRequiresCaptcha(Boolean(data?.requiresCaptcha));
      } catch (_) {
        setRequiresCaptcha(false);
        setCaptchaAnswer("");
      }
    }, 300);

    return () => clearTimeout(timer);
  }, [email]);

  useEffect(() => {
    const a = Math.floor(Math.random() * 10) + 1;
    const b = Math.floor(Math.random() * 10) + 1;
    setCaptchaQuestion({ a, b, answer: a + b });
  }, []);

  useEffect(() => {
    if (canvasRef.current && captchaQuestion.a !== undefined) {
      const ctx = canvasRef.current.getContext("2d");
      canvasRef.current.width = 140;
      canvasRef.current.height = 44;

      ctx.clearRect(0, 0, 140, 44);
      ctx.fillStyle = "#f4f4f5";
      ctx.fillRect(0, 0, 140, 44);

      for (let i = 0; i < 6; i++) {
        ctx.strokeStyle = "rgba(17,24,39,0.35)";
        ctx.beginPath();
        ctx.moveTo(Math.random() * 140, Math.random() * 44);
        ctx.lineTo(Math.random() * 140, Math.random() * 44);
        ctx.stroke();
      }

      ctx.font = "700 30px monospace";
      ctx.fillStyle = "#111827";
      ctx.textBaseline = "middle";
      ctx.fillText(`${captchaQuestion.a}+${captchaQuestion.b}=?`, 8, 22);
    }
  }, [captchaQuestion, requiresCaptcha]);

  const validateEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const isPhoneLike = (value) => /^\+?\d[\d\s-]{8,}$/.test(String(value).trim());
  const validateIdentifier = (value) => {
    const v = String(value).trim();
    return validateEmail(v.toLowerCase()) || String(v).replace(/\D/g, "").length === 10;
  };

  const refreshCaptcha = () => {
    const a = Math.floor(Math.random() * 10) + 1;
    const b = Math.floor(Math.random() * 10) + 1;
    setCaptchaQuestion({ a, b, answer: a + b });
    setCaptchaAnswer("");
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!email || !password) {
      toast.error("Please fill in all fields");
      return;
    }

    if (!validateIdentifier(email)) {
      toast.error("Enter a valid email address or 10-digit phone number");
      return;
    }

    if (requiresCaptcha) {
      if (!captchaAnswer) {
        toast.error("Please solve captcha");
        return;
      }

      if (parseInt(captchaAnswer) !== captchaQuestion.answer) {
        toast.error("Captcha is incorrect");
        return;
      }
    }

    const rawId = email.trim();
    const identifier = isPhoneLike(rawId)
      ? rawId.replace(/\D/g, "").slice(-10)
      : rawId.toLowerCase();
    dispatch(loginUser({ identifier, email: identifier, password }));
  };

  const handleSendOtp = async () => {
    const d10 = otpMobile.replace(/\D/g, "").slice(-10);
    if (d10.length !== 10) {
      toast.error("Enter a valid 10-digit phone number");
      return;
    }
    setOtpLoading(true);
    try {
      await axios.post(
        `${import.meta.env.VITE_BACKEND_URL}/api/users/otp/send`,
        { mobile: d10 }
      );
      toast.success("OTP sent to your WhatsApp");
      setOtpStep("otp");
    } catch (error) {
      toast.error(error.response?.data?.message || "Failed to send OTP");
    } finally {
      setOtpLoading(false);
    }
  };

  const handleVerifyOtp = async () => {
    if (!otpCode) {
      toast.error("Enter the OTP");
      return;
    }
    setOtpLoading(true);
    try {
      const d10 = otpMobile.replace(/\D/g, "").slice(-10);
      const { data } = await axios.post(
        `${import.meta.env.VITE_BACKEND_URL}/api/users/otp/verify`,
        { mobile: d10, otp: otpCode }
      );
      if (data.isNewUser) {
        toast.success("Number verified! Just one more step.");
        setOtpStep("name");
      } else {
        dispatch(googleLoginSuccess({ user: data.user, token: data.token }));
        toast.success("Login successful!");
        navigate(redirect);
      }
    } catch (error) {
      toast.error(error.response?.data?.message || "Incorrect or expired OTP");
    } finally {
      setOtpLoading(false);
    }
  };

  const handleCompleteSignup = async () => {
    if (!otpName.trim()) {
      toast.error("Enter your name");
      return;
    }
    setOtpLoading(true);
    try {
      const d10 = otpMobile.replace(/\D/g, "").slice(-10);
      const { data } = await axios.post(
        `${import.meta.env.VITE_BACKEND_URL}/api/users/otp/complete-signup`,
        { mobile: d10, name: otpName.trim() }
      );
      dispatch(googleLoginSuccess({ user: data.user, token: data.token }));
      toast.success("Account created — you're logged in!");
      navigate(redirect);
    } catch (error) {
      toast.error(error.response?.data?.message || "Failed to create account");
    } finally {
      setOtpLoading(false);
    }
  };

  // ---- NEW DESIGN FOLLOWS ----
  return (
    <div className="flex h-[80vh]" style={{ fontFamily: "Manrope, sans-serif", background: "#F6F1EA" }}>
      <div
        className="w-full md:w-full flex flex-col justify-center items-center p-6 sm:p-12"
        style={{ background: "#D6F1FF" }}
      >
        <form
          onSubmit={handleSubmit}
          className="w-full max-w-md p-8"
          style={{
            background: "transparent",
            display: "flex",
            flexDirection: "column",
            gap: 24,
          }}
        >
          {/* Header */}
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <h1
              style={{
                margin: 0,
                fontFamily: "Fraunces, serif",
                fontSize: 40,
                fontWeight: 600,
                color: "#000000",
                opacity: 1,
                textAlign: "center",
              }}
            >
              Welcome Back
            </h1>
            <p style={{ margin: 0, fontSize: 15, color: "#5F574F", textAlign: "center" }}>
              Log in or create an account with your phone number.
            </p>
          </div>

          {/* OTP MODE (default) */}
          {loginMode === "otp" && (
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {otpStep === "mobile" && (
                <>
                  <label
                    htmlFor="phone"
                    style={{ fontSize: 13, fontWeight: 600, color: "#3A342E" }}
                  >
                    Phone number
                  </label>
                  <div
                    style={{
                      display: "flex",
                      height: 52,
                      border: "1px solid #7DD3FC",
                      borderRadius: 12,
                      background: "#FFFFFF",
                      overflow: "hidden",
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        padding: "0 16px",
                        borderRight: "1px solid #E6DDD2",
                        fontSize: 15,
                        fontWeight: 600,
                        color: "#3A342E",
                      }}
                    >
                      +91
                    </div>
                    <input
                      id="phone"
                      type="tel"
                      placeholder="10-digit mobile number"
                      value={otpMobile}
                      onChange={(e) =>
                        setOtpMobile(e.target.value.replace(/\D/g, "").slice(0, 10))
                      }
                      onBlur={() => setOtpMobileTouched(true)}
                      inputMode="numeric"
                      maxLength={10}
                      style={{
                        flexGrow: 1,
                        border: 0,
                        outline: "none",
                        padding: "0 16px",
                        fontFamily: "Manrope, sans-serif",
                        fontSize: 15,
                        background: "transparent",
                      }}
                    />
                  </div>
                  {otpMobileTouched && otpMobile.length > 0 && otpMobile.length !== 10 && (
                    <p style={{ margin: 0, fontSize: 12, color: "#ef4444" }}>
                      Enter a valid 10-digit phone number
                    </p>
                  )}
                  <div className={otpMobileTouched && otpMobile.length !== 10 ? "mt-0 mb-4" : "mt-3 mb-4"}>
                    <button
                      type="button"
                      onClick={() => setLoginMode("password")}
                      className="text-sm text-sky-600 hover:underline font-medium text-right"
                    >
                      Login with Email &amp; Password instead
                    </button>
                  </div>
                  <button
                    type="button"
                    onClick={handleSendOtp}
                    disabled={otpLoading || otpMobile.length !== 10}
                    style={{
                      height: 52,
                      border: 0,
                      borderRadius: 12,
                      color: "#000000",
                      fontFamily: "Manrope, sans-serif",
                      fontSize: 15,
                      fontWeight: 700,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      gap: 10,
                      cursor: "pointer",
                      background: "#7DD3FC",
                      opacity: 1,
                    }}
                  >
                    {!otpLoading && <FaWhatsapp style={{ fontSize: 20, color: "#000000" }} />}
                    {otpLoading ? "Sending..." : "Send OTP on WhatsApp"}
                  </button>
                  <button
                    type="button"
                    onClick={() => setLoginMode("password")}
                    style={{
