    doc.text(buyerAddress, 120, 62, { maxWidth: 80 });

    // ✅ Product Table
    autoTable(doc, {
      startY: 72,
      head: [["#", "Description", "Variant", "SKU / HSN", "Qty", "Rate", "Per", "GST %", "Amount"]],
