                  <td className="py-3.5 px-6 text-right tabular-nums">
                    ₹{filteredProducts.reduce((sum, p) => sum + p.totalRevenue, 0).toFixed(2)}
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

