import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "sonner";
import axios from "axios";

const SubmitReviewFromOrder = () => {
  const { orderId } = useParams();
  const navigate = useNavigate();
  const { user } = useSelector((state) => state.auth);

  const [order, setOrder] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");
  const [image, setImage] = useState("");
  const [uploading, setUploading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);

  const CLOUDINARY_CLOUD_NAME = "dqj64anbj";
  const CLOUDINARY_UPLOAD_PRESET = "review_uploads";

  useEffect(() => {
    fetchOrder();
  }, [orderId]);

  const fetchOrder = async () => {
    try {
      const response = await axios.get(`/api/orders/${orderId}`, {
        headers: { Authorization: `Bearer ${user.token}` }
      });
      setOrder(response.data);
      // Auto-select first product if only one item
    //   if (response.data.orderItems.length === 1) {
    //     setSelectedProduct(response.data.orderItems[0]);
    //   }
    } catch (error) {
      console.error("Error fetching order:", error);
      toast.error("Failed to fetch order details");
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error("Please select an image file");
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error("Image size should be less than 5MB");
      return;
    }

    const formData = new FormData();
    formData.append("file", file);
    formData.append("upload_preset", CLOUDINARY_UPLOAD_PRESET);

    try {
      setUploading(true);
      const res = await axios.post(
        `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/image/upload`,
        formData
      );
      
      if (res.data && res.data.secure_url) {
        setImage(res.data.secure_url);
        toast.success("Image uploaded successfully");
      }
    } catch (err) {
      console.error("Image upload error:", err);
      toast.error("Image upload failed");
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!selectedProduct) {
      toast.error("Please select a product to review");
      return;
    }

    if (!rating || !comment.trim()) {
      toast.error("Please provide both rating and comment");
      return;
    }

    try {
      setSubmitting(true);
      
      await axios.post(
        `/api/products/${selectedProduct.product}/reviews`,
        { 
          rating: Number(rating), 
          comment: comment.trim(), 
          image: image || undefined 
        },
        { 
          headers: { 
            Authorization: `Bearer ${user.token}`,
            'Content-Type': 'application/json',
          }
        }
      );

      toast.success("Review submitted successfully");
      navigate("/my-orders");
    } catch (err) {
      console.error("Review submission error:", err);
      const errorMessage = err.response?.data?.message || "Failed to submit review";
      toast.error(errorMessage);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return <div className="text-center py-8">Loading order details...</div>;
  }

  if (!order) {
    return <div className="text-center py-8">Order not found</div>;
  }

  return (
    <div className="max-w-2xl mx-auto mt-10 bg-white p-8 rounded-xl shadow-xl border border-sky-100">
      <h2 className="text-2xl font-bold mb-6 text-sky-700">Write a Review</h2>
      
      {/* Product Selection */}
      {/* {order.orderItems.length > 1 && (
        <div className="mb-6">
          <label className="block mb-2 font-medium text-gray-700">
            Select Product to Review:
          </label>
          <div className="space-y-2">
            {order.orderItems.map((item, index) => (
              <div 
                key={index}
                className={`p-3 border rounded-lg cursor-pointer transition-colors ${
                  selectedProduct === item 
                    ? 'border-sky-500 bg-sky-50' 
                    : 'border-gray-200 hover:border-gray-300'
                }`}
                onClick={() => setSelectedProduct(item)}
              >
                <div className="flex items-center gap-3">
                  <img 
                    src={item.image} 
                    alt={item.name}
                    className="w-12 h-12 object-cover rounded"
                  />
                  <div>
                    <h4 className="font-medium">{item.name}</h4>
                    <p className="text-sm text-gray-600">₹{item.price}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )} */}

      {/* Selected Product Display */}
      {selectedProduct && (
        <div className="mb-6 p-4 bg-gray-50 rounded-lg">
          <h3 className="font-medium text-gray-700 mb-2">Reviewing:</h3>
          <div className="flex items-center gap-3">
            <img 
              src={selectedProduct.image} 
              alt={selectedProduct.name}
              className="w-16 h-16 object-cover rounded"
            />
            <div>
              <h4 className="font-medium">{selectedProduct.name}</h4>
              <p className="text-sm text-gray-600">₹{selectedProduct.price}</p>
            </div>
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-5">
        <div>
          <label className="block mb-1 font-medium text-gray-700">Rating *</label>
          <select
            value={rating}
            onChange={(e) => setRating(Number(e.target.value))}
            className="w-full border rounded-md px-4 py-2 bg-white outline-sky-300"
            required
          >
            <option value="">Select rating</option>
            {[1, 2, 3, 4, 5].map((star) => (
              <option key={star} value={star}>
                {star} Star{star > 1 && "s"}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="block mb-1 font-medium text-gray-700">Comment *</label>
          <textarea
            rows="4"
            value={comment}
            onChange={(e) => setComment(e.target.value)}
            className="w-full border rounded-md px-4 py-2 bg-white outline-sky-300"
            placeholder="Share your experience with this product..."
            required
            maxLength={500}
          />
          <div className="text-xs text-gray-500 mt-1">
            {comment.length}/500 characters
          </div>
        </div>

        <div>
          <label className="block mb-1 font-medium text-gray-700">
            Upload Image (optional)
          </label>
          <input
            type="file"
            accept="image/*"
            onChange={handleImageUpload}
            className="w-full text-sm border rounded-md px-3 py-2"
            disabled={uploading}
          />
          {uploading && (
            <p className="text-xs text-blue-600 mt-1">Uploading image...</p>
          )}
          {image && (
            <div className="mt-3">
              <img 
                src={image} 
                alt="Review preview" 
                className="w-32 h-32 object-cover rounded-md border"
              />
              <button
                type="button"
                onClick={() => setImage("")}
                className="text-xs text-red-600 hover:underline mt-1"
              >
                Remove image
              </button>
            </div>
          )}
        </div>

        <button
          type="submit"
          disabled={uploading || submitting || !rating || !comment.trim() || !selectedProduct}
          className="w-full py-3 px-4 bg-sky-600 text-white font-semibold rounded-md hover:bg-sky-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {submitting ? "Submitting..." : "Submit Review"}
        </button>
      </form>
    </div>
  );
};

export default SubmitReviewFromOrder;

import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { toast } from "sonner";
import axios from "axios";
import { updateProfile } from "../redux/slices/authSlice";

const UpdateProfile = () => {
  const dispatch = useDispatch();
  const { user, loading, error } = useSelector((state) => state.auth);

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    password: "",
    photo: "",
  });
  const [uploading, setUploading] = useState(false);
  const [greeting, setGreeting] = useState("");

  useEffect(() => {
    const updateGreeting = () => {
      const hour = new Date().getHours();
      if (hour < 12) setGreeting("Good Morning");
      else if (hour < 17) setGreeting("Good Afternoon");
      else if (hour < 21) setGreeting("Good Evening");
      else setGreeting("Good Night");
    };
    updateGreeting();
    const interval = setInterval(updateGreeting, 60 * 1000);
    return () => clearInterval(interval);
  }, []);
  const [profile, setProfile] = useState(null);

  const fetchUserProfile = async () => {
    try {
      const { data } = await axios.get(
        `${import.meta.env.VITE_BACKEND_URL}/api/users/profile`,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("userToken")}`,
          },
        }
      );
      setProfile(data); // Save full user object from DB
    } catch (error) {
      console.error("Failed to fetch profile:", error);
      toast.error("Could not fetch profile");
    }
  };
  useEffect(() => {
    fetchUserProfile();
  }, []);

  useEffect(() => {
    if (user) {
      setFormData({
        name: user.name || "",
        email: user.email || "",
        password: "",
        photo: user.photo || "",
      });
    }
  }, [user]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formDataCloud = new FormData();
    formDataCloud.append("image", file);
    try {
      setUploading(true);
      const { data } = await axios.post(
        `${import.meta.env.VITE_BACKEND_URL}/api/upload`,
        formDataCloud,
        {
          headers: {
            "Content-Type": "multipart/form-data",
            Authorization: `Bearer ${localStorage.getItem("userToken")}`,
          },
        }
      );
      setFormData((prev) => ({ ...prev, photo: data.imageUrl }));
      setUploading(false);
    } catch (error) {
      setUploading(false);
      toast.error("Image upload failed");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.name || !formData.email) {
      toast.error("Name and email are required");
      return;
    }
    const result = await dispatch(updateProfile(formData));
    if (result?.meta?.requestStatus === "fulfilled") {
      // toast.success("Profile updated successfully");
      fetchUserProfile(); // 🔄 refresh from DB
    } else {
      toast.error("Failed to update profile");
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-6">
      <h2 className="text-2xl font-bold mb-4">Update Profile</h2>
      {loading && <p className="text-blue-600 font-medium">Loading...</p>}
      {error && <p className="text-red-500 font-medium">Error: {error}</p>}

      {user && (
        <div className="relative bg-gradient-to-r from-blue-50 via-white to-blue-50 border border-blue-100 shadow-xl rounded-xl mb-8 p-6 sm:flex sm:items-center sm:justify-between transition-all duration-300">
          <div className="flex items-center gap-4">
            {profile?.photo ? (
              <img
                src={profile.photo}
                alt="Profile"
                onError={(e) => {
                  e.target.onerror = null;
                  e.target.src = "/default-avatar.png";
                }}
                className="w-16 h-16 rounded-full object-cover border-4 border-white shadow-md"
              />
            ) : (
              <div className="w-16 h-16 rounded-full bg-gradient-to-br from-blue-500 to-sky-500 text-white flex items-center justify-center text-2xl font-bold shadow-md ring-4 ring-white">
                {profile?.name?.charAt(0).toUpperCase() || "?"}
              </div>
            )}

            <div>
              <h3 className="text-2xl font-bold text-blue-800 mb-1">
                {greeting}, {user.name}
              </h3>
              <p className="text-sm text-gray-600">
                <span className="font-medium">Role:</span>{" "}
                <span
                  className={`inline-block px-2 py-0.5 rounded-full text-xs font-semibold ${
                    user.role === "admin"
                      ? "bg-red-100 text-red-700"
                      : user.role === "merchantise"
                      ? "bg-purple-100 text-purple-700"
                      : user.role === "delivery_boy"
                      ? "bg-yellow-100 text-yellow-700"
                      : "bg-green-100 text-green-700"
                  }`}
                >
                  {user.role
                    .replace("_", " ")
                    .replace(/\b\w/g, (c) => c.toUpperCase())}
                </span>
              </p>
              <p className="text-sm text-gray-600">
                <span className="font-medium">Email:</span> {user.email}
              </p>
              {/* <p className="text-xs text-gray-400 mt-1">
                <span className="font-medium">User ID:</span> {user._id}
              </p> */}
            </div>
          </div>
        </div>
      )}

      <div className="p-6 bg-white shadow-md rounded-lg mb-6">
        <h3 className="text-lg font-bold mb-6">Edit Your Details</h3>
        <form onSubmit={handleSubmit}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label
                htmlFor="name"
                className="block text-gray-700 mb-1 font-medium"
              >
                Name
              </label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-400"
                required
              />
            </div>
            <div>
              <label
                htmlFor="email"
                className="block text-gray-700 mb-1 font-medium"
              >
                Email
              </label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-400"
                required
              />
            </div>
            <div>
              <label
                htmlFor="password"
                className="block text-gray-700 mb-1 font-medium"
              >
                New Password <span className="text-gray-400">(optional)</span>
              </label>
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-300 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-400"
              />
            </div>
            <div>
              <label
                htmlFor="photo"
                className="block text-sm font-medium text-gray-700 mb-1"
              >
                Profile Picture
              </label>

              <div className="flex items-center gap-4">
                {/* Preview if available */}
                {formData.photo ? (
                  <img
                    src={formData.photo}
                    alt="Preview"
                    className="w-14 h-14 rounded-full object-cover border-2 border-blue-500 shadow-sm"
                  />
                ) : (
                  <div className="w-14 h-14 rounded-full bg-gray-200 flex items-center justify-center text-blue-600 font-bold text-lg border-2 border-gray-300 shadow-sm">
                    {formData.name?.charAt(0).toUpperCase() || "?"}
                  </div>
                )}

                <div className="flex-1">
                  <input
                    type="file"
                    id="photo"
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="block w-full text-sm text-gray-600 bg-white border border-gray-300 rounded-md shadow-sm cursor-pointer file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100 transition"
                  />
                  {uploading && (
                    <p className="text-blue-500 text-xs mt-1">Uploading...</p>
                  )}
                </div>
              </div>
            </div>
          </div>

          <div className="mt-6">
            <button
              type="submit"
              className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-6 rounded shadow"
              disabled={loading || uploading}
            >
              {loading || uploading ? "Updating..." : "Update Profile"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default UpdateProfile;

import React, { useEffect, useState } from "react";
import axios from "axios";
import { toast } from "sonner";
import { Toaster } from "sonner";
import { FaTrashAlt, FaReply } from "react-icons/fa";

const ViewContacts = () => {
  const [contacts, setContacts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [showReplyForm, setShowReplyForm] = useState(false);
  const [replyTo, setReplyTo] = useState(null);
  const [replyContent, setReplyContent] = useState({
    subject: "",
    message: "",
  });
  const [confirmDeleteId, setConfirmDeleteId] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const messagesPerPage = 5;
  const [viewMsg, setViewMsg] = useState(null);
  const [sortField, setSortField] = useState("createdAt");
  const [sortOrder, setSortOrder] = useState("desc");

  const handleSort = (field) => {
    if (sortField === field) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortOrder("asc");
    }
  };

  useEffect(() => {
    const fetchContacts = async () => {
      try {
        const token = localStorage.getItem("userToken");
        const res = await axios.get(
          `${import.meta.env.VITE_BACKEND_URL}/api/contact`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        setContacts(res.data);
      } catch (error) {
        toast.error("Failed to load contact messages");
      } finally {
        setLoading(false);
      }
    };
    fetchContacts();
  }, []);

  const handleDelete = async (id) => {
    try {
      const token = localStorage.getItem("userToken");
      await axios.delete(
        `${import.meta.env.VITE_BACKEND_URL}/api/contact/${id}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setContacts((prev) => prev.filter((msg) => msg._id !== id));
      toast.success("Message deleted");
    } catch (error) {
      toast.error("Failed to delete message");
    } finally {
      setConfirmDeleteId(null);
    }
  };

  // const filteredContacts = contacts.filter(
  //   (msg) =>
  //     msg.name.toLowerCase().includes(search.toLowerCase()) ||
  //     msg.email.toLowerCase().includes(search.toLowerCase())
  // );

  const filteredContacts = contacts
    .filter(
      (msg) =>
        msg.name.toLowerCase().includes(search.toLowerCase()) ||
        msg.email.toLowerCase().includes(search.toLowerCase())
    )
    .sort((a, b) => {
      const aVal =
        sortField === "createdAt"
          ? new Date(a[sortField])
          : a[sortField].toLowerCase();
      const bVal =
        sortField === "createdAt"
          ? new Date(b[sortField])
          : b[sortField].toLowerCase();

      if (aVal < bVal) return sortOrder === "asc" ? -1 : 1;
      if (aVal > bVal) return sortOrder === "asc" ? 1 : -1;
      return 0;
    });

  const totalPages = Math.ceil(filteredContacts.length / messagesPerPage);
  const displayedContacts = filteredContacts.slice(
    (currentPage - 1) * messagesPerPage,
    currentPage * messagesPerPage
  );

  const openReply = (msg) => {
    setReplyTo(msg);
    setReplyContent({ subject: `Re: ${msg.subject}`, message: "" });
    setShowReplyForm(true);
  };

  const handleReplySubmit = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("userToken");
      await axios.post(
        `${import.meta.env.VITE_BACKEND_URL}/api/contact/reply`,
        {
          to: replyTo.email,
          subject: replyContent.subject,
          message: replyContent.message,
          audience: "reply",
          relatedContactId: replyTo._id,
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      toast.success(`Email sent to ${replyTo.email}`);
      setShowReplyForm(false);
    } catch (err) {
      toast.error("Failed to send reply email");
    }
  };

  return (
    <div className="p-4">
      <Toaster richColors position="top-right" />
      <h2 className="text-2xl font-bold text-gray-800 mb-4">
        Contact Messages
      </h2>

      <input
        type="text"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        placeholder="Search by name or email..."
        className="bg-white mb-4 w-full max-w-md px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-1 focus:ring-sky-500"
      />

      {loading ? (
        <p className="text-center text-gray-500">Loading messages...</p>
      ) : displayedContacts.length === 0 ? (
        <p className="text-center text-gray-400">No messages found.</p>
      ) : (
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-100 text-left text-sm font-semibold text-gray-700">
              <tr>
                <th
                  className="px-4 py-3 cursor-pointer select-none"
                  onClick={() => handleSort("createdAt")}
                >
                  Date{" "}
                  {sortField === "createdAt" &&
                    (sortOrder === "asc" ? "▲" : "▼")}
                </th>
                <th
                  className="px-4 py-3 cursor-pointer select-none"
                  onClick={() => handleSort("name")}
                >
                  Name{" "}
                  {sortField === "name" && (sortOrder === "asc" ? "▲" : "▼")}
                </th>

                <th className="px-4 py-3">Email</th>
                <th className="px-4 py-3">Subject</th>
                <th className="px-4 py-3">Message</th>
                <th className="px-4 py-3 text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-100 text-sm">
              {displayedContacts.map((msg) => (
                <tr key={msg._id} className="hover:bg-gray-50">
                  <td className="px-4 py-2">
                    {new Date(msg.createdAt).toLocaleDateString("en-IN", {
                      day: "2-digit",
                      month: "short",
                      year: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </td>
                  <td className="px-4 py-2">{msg.name}</td>
                  <td className="px-4 py-2">{msg.email}</td>
                  <td className="px-4 py-2">{msg.subject}</td>
                  <td
                    className="px-4 py-2 max-w-xs truncate"
                    title={msg.message}
                  >
                    {msg.message}
                  </td>
                  <td className="px-4 py-2 text-center">
                    <div className="flex justify-center gap-2">
                      <button
                        onClick={() => setViewMsg(msg)}
                        className="text-gray-600 hover:text-gray-800 text-sm px-2 py-1 border border-gray-300 rounded-md"
                      >
                        View
                      </button>
                      <button
                        onClick={() => openReply(msg)}
                        className="text-sky-600 hover:text-sky-800 text-sm p-2 rounded-full hover:bg-sky-100"
                        title="Reply"
                      >
                        <FaReply />
                      </button>
                      <button
                        onClick={() => setConfirmDeleteId(msg._id)}
                        className="text-red-600 hover:text-red-800 text-sm p-2 rounded-full hover:bg-red-100"
                        title="Delete"
                      >
                        <FaTrashAlt />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {totalPages > 1 && (
        <div className="flex justify-center mt-6 gap-2">
          {[...Array(totalPages)].map((_, i) => (
            <button
              key={i}
              onClick={() => setCurrentPage(i + 1)}
              className={`px-3 py-1.5 rounded-full text-sm font-medium transition ${
                currentPage === i + 1
                  ? "bg-sky-600 text-white"
                  : "bg-gray-200 text-gray-700 hover:bg-gray-300"
              }`}
            >
              {i + 1}
            </button>
          ))}
        </div>
      )}

      {viewMsg && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl shadow-xl w-full max-w-xl">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">
              Message Details
            </h3>
            <p className="text-sm text-gray-700 mb-1">
              <strong>Date:</strong>{" "}
              {new Date(viewMsg.createdAt).toLocaleString("en-IN")}
            </p>
            <p className="text-sm text-gray-700 mb-1">
              <strong>Name:</strong> {viewMsg.name}
            </p>
            <p className="text-sm text-gray-700 mb-1">
              <strong>Email:</strong> {viewMsg.email}
            </p>
            <p className="text-sm text-gray-700 mb-1">
              <strong>Subject:</strong> {viewMsg.subject}
            </p>
            <p className="text-sm text-gray-800 mt-4 whitespace-pre-line border-t pt-3 max-h-60 overflow-y-auto pr-2">
              <strong>Message:</strong>
              <br />
              {viewMsg.message}
            </p>
            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={() => setViewMsg(null)}
                className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 text-sm"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {confirmDeleteId && (
        <div className="fixed inset-0 bg-black/40 bg-opacity-40 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl shadow-xl w-full max-w-md">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">
              Are you sure?
            </h3>
            <p className="text-sm text-gray-600 mb-6">
              This will permanently delete the message.
            </p>
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setConfirmDeleteId(null)}
                className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 text-sm"
              >
                Cancel
              </button>
              <button
                onClick={() => handleDelete(confirmDeleteId)}
                className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 text-sm"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}

      {showReplyForm && (
        <div className="fixed inset-0 bg-black/40 bg-opacity-40 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl shadow-xl w-full max-w-lg">
            <h3 className="text-lg font-semibold text-gray-800 mb-2">
              Reply to {replyTo.email}
            </h3>
            <form onSubmit={handleReplySubmit} className="space-y-4">
              <input
                type="text"
                onChange={(e) =>
                  setReplyContent({ ...replyContent, subject: e.target.value })
                }
                placeholder="Subject"
                className="w-full border border-gray-300 px-3 py-2 rounded-md"
              />
              <textarea
                rows="4"
                value={replyContent.message}
                onChange={(e) =>
                  setReplyContent({ ...replyContent, message: e.target.value })
                }
                placeholder="Your message"
                className="w-full border border-gray-300 px-3 py-2 rounded-md"
              />
              <div className="flex justify-end gap-3">
                <button
                  type="button"
                  onClick={() => setShowReplyForm(false)}
                  className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 text-sm"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-sky-600 text-white rounded hover:bg-sky-700 text-sm"
                >
                  Send Reply
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ViewContacts;

import React, { useEffect, useState } from "react";
import axios from "axios";
import { toast, Toaster } from "sonner";
import { FaTrashAlt } from "react-icons/fa";

const ViewSubscribers = () => {
  const [subscribers, setSubscribers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [confirmDeleteId, setConfirmDeleteId] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 6;

  useEffect(() => {
    const fetchSubscribers = async () => {
      try {
        const res = await axios.get(
          `${import.meta.env.VITE_BACKEND_URL}/api/subscribers`
        );
        setSubscribers(res.data);
      } catch (error) {
        toast.error("Failed to load subscribers");
      } finally {
        setLoading(false);
      }
    };
    fetchSubscribers();
  }, []);

  const handleDelete = async (id) => {
    try {
      await axios.delete(`${import.meta.env.VITE_BACKEND_URL}/api/subscribers/${id}`);
      setSubscribers((prev) => prev.filter((sub) => sub._id !== id));
      toast.success("Subscriber deleted");
    } catch (error) {
      toast.error("Failed to delete subscriber");
    } finally {
      setConfirmDeleteId(null);
    }
  };

  const filtered = subscribers.filter((sub) =>
    sub.email.toLowerCase().includes(search.toLowerCase())
  );

  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const displayed = filtered.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  return (
    <div className="p-4">
      <Toaster position="top-right" />
      <h2 className="text-2xl font-bold text-gray-800 mb-4">Newsletter Subscribers</h2>

      <div className="flex justify-between items-center gap-4 mb-4">
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search by email..."
          className="bg-white w-full max-w-md px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-1 focus:ring-sky-500"
        />
        <span className="inline-block px-3 py-1 bg-sky-600 text-white rounded-full text-sm font-semibold shadow-sm">
          Total Subscribers: {subscribers.length}
        </span>
      </div>


      {loading ? (
        <p className="text-center text-gray-500">Loading subscribers...</p>
      ) : displayed.length === 0 ? (
        <p className="text-center text-gray-400">No subscribers found.</p>
      ) : (
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-100 text-left text-sm font-semibold text-gray-700">
              <tr>
                <th className="px-4 py-3">Email</th>
                {/* <th className="px-4 py-3">IP Address</th> */}
                <th className="px-4 py-3">Subscribed On</th>
                <th className="px-4 py-3 text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-100 text-sm">
              {displayed.map((sub) => (
                <tr key={sub._id} className="hover:bg-gray-50">
                  <td className="px-4 py-2">{sub.email}</td>
                  {/* <td className="px-4 py-2">{sub.ipAddress || "N/A"}</td> */}
                  <td className="px-4 py-2">
                    {new Date(sub.subscribedAt).toLocaleString("en-IN", {
                      day: "2-digit",
                      month: "short",
                      year: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </td>
                  <td className="px-4 py-2 text-center">
                    <button
                      onClick={() => setConfirmDeleteId(sub._id)}
                      className="text-red-600 hover:text-red-800 text-sm p-2 rounded-full hover:bg-red-100"
                      title="Delete"
                    >
                      <FaTrashAlt />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {totalPages > 1 && (
        <div className="flex justify-center mt-6 gap-2">
          {[...Array(totalPages)].map((_, i) => (
            <button
              key={i}
              onClick={() => setCurrentPage(i + 1)}
              className={`px-3 py-1.5 rounded-full text-sm font-medium transition ${currentPage === i + 1
                  ? "bg-sky-600 text-white"
                  : "bg-gray-200 text-gray-700 hover:bg-gray-300"
                }`}
            >
              {i + 1}
            </button>
          ))}
        </div>
      )}

      {confirmDeleteId && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl shadow-xl w-full max-w-md">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Are you sure?</h3>
            <p className="text-sm text-gray-600 mb-6">
              This will permanently delete the subscriber.
            </p>
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setConfirmDeleteId(null)}
                className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 text-sm"
              >
                Cancel
              </button>
              <button
                onClick={() => handleDelete(confirmDeleteId)}
                className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 text-sm"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ViewSubscribers;

import React, { useEffect, useState } from "react";
import { toast } from "sonner";
import { FaCheckCircle, FaEdit, FaTrash, FaSearch } from "react-icons/fa";
import { MdOutlineAssignment, MdFilterList } from "react-icons/md";
import { HiChevronLeft, HiChevronRight } from "react-icons/hi2";

/* ── status config ── */
const STATUS = {
  completed:     { label: "Completed",     pill: "bg-emerald-100 text-emerald-700 border-emerald-200", bar: "bg-emerald-500", pct: "w-full",  dot: "bg-emerald-500" },
  working:       { label: "In Progress",   pill: "bg-amber-100   text-amber-700   border-amber-200",   bar: "bg-amber-400",   pct: "w-2/3",   dot: "bg-amber-400"   },
  "not-completed":{ label: "Not Started",  pill: "bg-red-100     text-red-600     border-red-200",     bar: "bg-red-400",     pct: "w-0",     dot: "bg-red-400"     },
};
const getStatus = (s) => STATUS[s] || STATUS["not-completed"];

const ViewTasks = () => {
  const [tasks,         setTasks]         = useState([]);
  const [filteredTasks, setFilteredTasks] = useState([]);
  const [searchTerm,    setSearchTerm]    = useState("");
  const [statusFilter,  setStatusFilter]  = useState("");
  const [currentPage,   setCurrentPage]   = useState(1);
  const [editingId,     setEditingId]     = useState(null);
  const [editForm,      setEditForm]      = useState({ title: "", description: "" });
  const [deleteModal,   setDeleteModal]   = useState({ open: false, id: null });

  const TASKS_PER_PAGE = 5;
  const userInfo = JSON.parse(localStorage.getItem("userInfo") || "{}");
  const isAdmin = userInfo?.role === "admin";

  /* ── data ── */
  const fetchTasks = async () => {
    try {
      const url = isAdmin
        ? `${import.meta.env.VITE_BACKEND_URL}/api/tasks`
        : `${import.meta.env.VITE_BACKEND_URL}/api/tasks/user/${userInfo.email}`;
      const data = await fetch(url).then((r) => r.json());
      setTasks(data);
    } catch { toast.error("Failed to fetch tasks"); }
  };

  useEffect(() => { fetchTasks(); }, []);

  useEffect(() => {
    let list = [...tasks];
    if (searchTerm && isAdmin)
      list = list.filter((t) =>
        t.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        t.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        t.title?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    if (statusFilter && statusFilter !== "all")
      list = list.filter((t) => t.status === statusFilter);
    setFilteredTasks(list);
    setCurrentPage(1);
  }, [searchTerm, statusFilter, tasks]);

  const handleDelete = async (id) => {
    await fetch(`${import.meta.env.VITE_BACKEND_URL}/api/tasks/${id}`, { method: "DELETE" });
    toast.success("Task deleted");
    fetchTasks();
  };

  const handleStatusToggle = async (id, current) => {
    const next = current === "working" ? "completed" : "working";
    await fetch(`${import.meta.env.VITE_BACKEND_URL}/api/tasks/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status: next }),
    });
    toast.success("Status updated");
    fetchTasks();
  };

  const saveEdit = async (id) => {
    await fetch(`${import.meta.env.VITE_BACKEND_URL}/api/tasks/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(editForm),
    });
    toast.success("Task updated");
    setEditingId(null);
    fetchTasks();
  };

  /* ── pagination ── */
  const totalPages  = Math.ceil(filteredTasks.length / TASKS_PER_PAGE);
  const currentList = filteredTasks.slice((currentPage - 1) * TASKS_PER_PAGE, currentPage * TASKS_PER_PAGE);

  /* ── stats ── */
  const totalCount     = tasks.length;
  const workingCount   = tasks.filter((t) => t.status === "working").length;
  const completedCount = tasks.filter((t) => t.status === "completed").length;

  return (
    <div className="min-h-screen p-4 md:p-6 space-y-5">

      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center shrink-0 shadow-sm">
            <MdOutlineAssignment className="text-white text-xl" />
          </div>
          <div>
            <h1 className="text-xl font-extrabold text-gray-900">{isAdmin ? "All Tasks" : "My Tasks"}</h1>
            <p className="text-xs text-gray-400 mt-0.5">{totalCount} task{totalCount !== 1 ? "s" : ""} total</p>
          </div>
        </div>

        {/* Summary chips */}
        <div className="flex gap-2 flex-wrap">
          {[
            { label: "Total",     val: totalCount,     dot: "bg-gray-400"    },
            { label: "Working",   val: workingCount,   dot: "bg-amber-400"   },
            { label: "Done",      val: completedCount, dot: "bg-emerald-500" },
          ].map(({ label, val, dot }) => (
            <div key={label} className="flex items-center gap-1.5 bg-white border border-gray-200 rounded-xl px-3 py-1.5 shadow-sm text-xs font-semibold text-gray-700">
              <span className={`w-2 h-2 rounded-full ${dot}`} />{label}: {val}
            </div>
          ))}
        </div>
      </div>

      {/* ── Filters ── */}
      <div className="p-4 flex flex-col sm:flex-row gap-3">
        {isAdmin && (
          <div className="relative flex-1">
            <FaSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs" />
            <input
              type="text"
              placeholder="Search by name, email or title…"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm bg-gray-50 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-400 transition"
            />
          </div>
        )}
        <div className="relative">
          <MdFilterList className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-base" />
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="pl-9 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm bg-gray-50 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-400 transition appearance-none cursor-pointer"
          >
            <option value="">All Status</option>
            <option value="working">In Progress</option>
            <option value="completed">Completed</option>
            <option value="not-completed">Not Started</option>
          </select>
        </div>
      </div>

      {/* ── Task list ── */}
      {currentList.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-gray-100 shadow-sm text-center">
          <div className="w-16 h-16 rounded-full bg-gray-50 flex items-center justify-center mb-3">
            <MdOutlineAssignment className="text-3xl text-gray-300" />
          </div>
          <p className="text-sm font-semibold text-gray-500">No tasks found</p>
          <p className="text-xs text-gray-400 mt-1">Try adjusting your filters</p>
        </div>
      ) : (
        <div className="space-y-3">
          {currentList.map((task) => {
            const st = getStatus(task.status);
            return (
              <div
                key={task._id}
                className="bg-white border border-gray-100 rounded-2xl shadow-sm hover:shadow-md transition-all overflow-hidden"
              >
                {/* Coloured left accent */}
                <div className="flex">
                  <div className={`w-1 shrink-0 ${st.bar}`} />
                  <div className="flex-1 p-5">

                    {editingId === task._id ? (
                      /* ── Edit mode ── */
                      <div className="space-y-3">
                        <input
                          type="text"
                          value={editForm.title}
                          onChange={(e) => setEditForm((p) => ({ ...p, title: e.target.value }))}
                          className="w-full px-4 py-2.5 border border-gray-200 rounded-xl text-sm bg-gray-50 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-400 transition font-semibold"
                          placeholder="Task title"
                        />
                        <textarea
                          rows={3}
                          value={editForm.description}
                          onChange={(e) => setEditForm((p) => ({ ...p, description: e.target.value }))}
                          className="w-full px-4 py-2.5 border border-gray-200 rounded-xl text-sm bg-gray-50 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-400 resize-none transition"
                          placeholder="Description"
                        />
                        <div className="flex gap-2">
                          <button
                            onClick={() => saveEdit(task._id)}
                            className="px-4 py-2 rounded-xl bg-indigo-600 text-white text-xs font-bold hover:bg-indigo-700 transition"
                          >
                            Save Changes
                          </button>
                          <button
                            onClick={() => setEditingId(null)}
                            className="px-4 py-2 rounded-xl border border-gray-200 text-gray-600 text-xs font-semibold hover:bg-gray-50 transition"
                          >
                            Cancel
                          </button>
                        </div>
                      </div>
                    ) : (
                      /* ── View mode ── */
                      <div>
                        {/* Top row */}
                        <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3 mb-3">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap mb-1">
                              <h3 className="text-base font-bold text-gray-900">{task.title}</h3>
                              <span className={`inline-flex items-center gap-1.5 text-[11px] font-bold px-2.5 py-0.5 rounded-full border ${st.pill}`}>
                                <span className={`w-1.5 h-1.5 rounded-full ${st.dot}`} />{st.label}
                              </span>
                            </div>
                            <p className="text-sm text-gray-500 leading-relaxed">{task.description}</p>
                          </div>
                        </div>

                        {/* Meta */}
                        <div className="flex flex-wrap gap-4 text-xs text-gray-400 mb-3">
                          {isAdmin && (
                            <span className="flex items-center gap-1">
                              <span className="font-semibold text-gray-600">{task.name}</span>
                              <span>·</span>
                              <span>{task.email}</span>
                            </span>
                          )}
                          <span>Created {new Date(task.createdAt).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })}</span>
                        </div>

                        {/* Progress bar */}
                        <div className="mb-4">
                          <div className="flex items-center justify-between text-[11px] text-gray-400 mb-1.5">
                            <span>Progress</span>
                            <span className="font-semibold">
                              {task.status === "completed" ? "100%" : task.status === "working" ? "66%" : "0%"}
                            </span>
                          </div>
                          <div className="h-1.5 w-full bg-gray-100 rounded-full overflow-hidden">
                            <div className={`h-full rounded-full transition-all duration-500 ${st.bar} ${st.pct}`} />
                          </div>
                        </div>

                        {/* Actions */}
                        <div className="flex flex-wrap items-center gap-2">
                          <button
                            onClick={() => handleStatusToggle(task._id, task.status)}
                            className="flex items-center gap-1.5 text-xs font-bold px-3 py-2 rounded-xl bg-indigo-50 text-indigo-700 border border-indigo-100 hover:bg-indigo-100 transition"
                          >
                            <FaCheckCircle className="text-xs" />
                            {task.status === "working" ? "Mark Complete" : "Mark Working"}
                          </button>
                          <button
                            onClick={() => { setEditingId(task._id); setEditForm({ title: task.title, description: task.description }); }}
                            className="flex items-center gap-1.5 text-xs font-bold px-3 py-2 rounded-xl bg-amber-50 text-amber-700 border border-amber-100 hover:bg-amber-100 transition"
                          >
                            <FaEdit className="text-xs" /> Edit
                          </button>
                          <button
                            onClick={() => setDeleteModal({ open: true, id: task._id })}
                            className="flex items-center gap-1.5 text-xs font-bold px-3 py-2 rounded-xl bg-red-50 text-red-600 border border-red-100 hover:bg-red-100 transition"
                          >
                            <FaTrash className="text-xs" /> Delete
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* ── Pagination ── */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button
            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="w-8 h-8 flex items-center justify-center rounded-xl border border-gray-200 text-gray-500 hover:bg-gray-100 disabled:opacity-40 disabled:cursor-not-allowed transition"
          >
            <HiChevronLeft />
          </button>
          {Array.from({ length: totalPages }, (_, i) => (
            <button
              key={i}
              onClick={() => setCurrentPage(i + 1)}
              className={`w-8 h-8 rounded-xl text-xs font-bold transition ${
                currentPage === i + 1
                  ? "bg-indigo-600 text-white shadow-sm"
                  : "border border-gray-200 text-gray-600 hover:bg-gray-100"
              }`}
            >
              {i + 1}
            </button>
          ))}
          <button
            onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="w-8 h-8 flex items-center justify-center rounded-xl border border-gray-200 text-gray-500 hover:bg-gray-100 disabled:opacity-40 disabled:cursor-not-allowed transition"
          >
            <HiChevronRight />
          </button>
        </div>
      )}

      {/* ── Delete confirm modal ── */}
      {deleteModal.open && (
        <div
          className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-center justify-center p-4"
          onClick={() => setDeleteModal({ open: false, id: null })}
        >
          <div
            className="bg-white rounded-2xl shadow-xl p-6 max-w-sm w-full"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="w-12 h-12 rounded-full bg-red-100 flex items-center justify-center mx-auto mb-4">
              <FaTrash className="text-red-500 text-lg" />
            </div>
            <h3 className="text-base font-bold text-gray-800 text-center mb-1">Delete Task?</h3>
            <p className="text-sm text-gray-500 text-center mb-5">This action cannot be undone.</p>
            <div className="flex gap-3">
              <button
                onClick={() => setDeleteModal({ open: false, id: null })}
                className="flex-1 py-2.5 rounded-xl border border-gray-200 text-sm font-semibold text-gray-600 hover:bg-gray-50 transition"
              >
                Cancel
              </button>
              <button
                onClick={() => { handleDelete(deleteModal.id); setDeleteModal({ open: false, id: null }); }}
                className="flex-1 py-2.5 rounded-xl bg-red-600 text-sm font-bold text-white hover:bg-red-700 transition shadow-sm"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

